/* ==== js/00-shell.js ==== */
/* NK15068 — shell: helpers every page uses (window.NKS), theme, More menu, dates, badges, share.
   Page modules register themselves as NKS.pages[<data-page>] = () => {…}; 99-boot.js runs the one for this page.
   All page text is already in the HTML; JS only refreshes live parts. */
(function () {
  "use strict";
  const doc = document.documentElement;
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fmt = (n) => Number(n).toLocaleString("en-US");
  const ROOT = doc.dataset.root || "";

  /* ---------------- storage, every call guarded ---------------- */
  const store = (area) => ({
    get(k) { try { return area().getItem(k); } catch (e) { return null; } },
    set(k, v) { try { area().setItem(k, v); return true; } catch (e) { return false; } },
    del(k) { try { area().removeItem(k); } catch (e) { /* ignore */ } },
    keys() { try { const a = area(), out = []; for (let i = 0; i < a.length; i++) out.push(a.key(i)); return out; } catch (e) { return []; } },
  });
  const local = store(() => localStorage), session = store(() => sessionStorage);
  const getJSONKey = (k, d) => { try { const v = JSON.parse(local.get(k)); return v ?? d; } catch (e) { return d; } };

  /* ---------------- credits by outlet name (same table as nkpages/fmt.py, from pubs.js) ---------------- */
  const PUBS = window.NK_PUBS || {};
  function pubName(u) {
    let url;
    try { url = new URL(u); } catch (e) { return ""; }
    const h = url.hostname.replace(/^www\./, ""), path = url.pathname.toLowerCase();
    if (h === "triblive.com" && path.includes("/valley-news-dispatch/")) return "Valley News Dispatch (TribLive)";
    if (h === "community.triblive.com") return "TribLive community news";
    if (h === "archive.triblive.com") return "Tribune-Review archive";
    if (h === "triblive.com" || h.endsWith(".triblive.com")) return "TribLive";
    if (PUBS[h]) return PUBS[h];
    if (h === "pa.gov" && path.startsWith("/agencies/pda")) return "PA Dept. of Agriculture";
    if (h.endsWith(".crimewatchpa.com")) return "CrimeWatch";
    if (h === "github.com" || h === "raw.githubusercontent.com") {
      if (path.startsWith("/jacobkap/")) return "FBI UCR via Jacob Kaplan";
      if (path.startsWith("/bencarneiro/ntsb")) return "PennDOT crash data";
      if (h === "raw.githubusercontent.com" && path.startsWith("/washingtonpost/")) return "Washington Post";
      return "GitHub dataset";
    }
    return h;
  }
  const pub = (u) => (u ? `<a class="cr" href="${esc(u)}" target="_blank" rel="noopener">${esc(pubName(u) || "source")}</a>` : "");
  function credit(urls, pre = "Source: ") {
    const seen = new Set(), out = [];
    for (const u of [].concat(urls || []).filter(Boolean)) {
      const n = pubName(u);
      if (!n || seen.has(n)) continue;
      seen.add(n); out.push(pub(u));
    }
    return out.length ? pre + out.join(", ") : "";
  }

  /* ---------------- AP-style dates (same rules as nkpages/fmt.py) ---------------- */
  const AP_MONTHS = ["Jan.", "Feb.", "March", "April", "May", "June", "July", "Aug.", "Sept.", "Oct.", "Nov.", "Dec."];
  const AP_DAYS = ["Sun.", "Mon.", "Tues.", "Wed.", "Thurs.", "Fri.", "Sat."];
  const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  function apDate(s, approx) {
    const m = String(s ?? "").match(/^(\d{4})(?:-(\d{1,2})(?:-(\d{1,2}))?)?/);
    if (!m) return String(s ?? "");
    let out = m[1];
    if (m[2] && AP_MONTHS[+m[2] - 1]) out = m[3] ? `${AP_MONTHS[+m[2] - 1]} ${+m[3]}, ${m[1]}` : `${AP_MONTHS[+m[2] - 1]} ${m[1]}`;
    return approx ? "About " + out : out;
  }
  /* a local calendar date from 'YYYY-MM-DD' (never parsed as UTC) */
  const day = (iso) => { const [y, m, d] = String(iso).slice(0, 10).split("-").map(Number); return new Date(y, m - 1, d); };
  const isoDay = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const apDay = (iso) => { const d = day(iso); return `${AP_DAYS[d.getDay()]}, ${AP_MONTHS[d.getMonth()]} ${d.getDate()}`; };
  const apLong = (iso, year = true) => { const d = day(iso); return `${DAYS[d.getDay()]}, ${AP_MONTHS[d.getMonth()]} ${d.getDate()}` + (year ? `, ${d.getFullYear()}` : ""); };
  function apTime(d) {
    const h = d.getHours(), mi = d.getMinutes();
    if (h === 12 && mi === 0) return "noon";
    const suf = h < 12 ? "a.m." : "p.m.", h12 = h % 12 || 12;
    return mi ? `${h12}:${String(mi).padStart(2, "0")} ${suf}` : `${h12} ${suf}`;
  }
  const today = () => { const n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); };
  const daysFrom = (iso) => Math.round((day(iso) - today()) / 864e5);
  /* "Today", "Tomorrow", "This Friday" (within 6 days), "" otherwise */
  function relDay(iso) {
    const n = daysFrom(iso);
    if (n === 0) return "Today";
    if (n === 1) return "Tomorrow";
    if (n > 1 && n < 7) return "This " + DAYS[day(iso).getDay()];
    return "";
  }
  /* "today", "yesterday", "3 days ago", "2 weeks ago" */
  function ago(iso) {
    const n = -daysFrom(iso);
    if (n <= 0) return "today";
    if (n === 1) return "yesterday";
    if (n < 14) return `${n} days ago`;
    if (n < 60) return `${Math.round(n / 7)} weeks ago`;
    return `${Math.round(n / 30)} months ago`;
  }
  /* relabel [data-rel-day] (text = relDay) and [data-ago] (text = "(3 days ago)" style when data-paren) */
  function relabel(root = document) {
    $$("[data-rel-day]", root).forEach((el) => { el.textContent = relDay(el.dataset.relDay); });
    $$("[data-ago]", root).forEach((el) => { const t = ago(el.dataset.ago); el.textContent = el.hasAttribute("data-paren") ? `(${t})` : t; });
  }

  /* ---------------- streets, routes, small text helpers ---------------- */
  const SHIELDED = new Set(["56", "366", "380", "780"]);
  function shield(ref) {
    const r = String(ref).trim().replace(/^(PA|SR)[\s-]*/i, "");
    if (!SHIELDED.has(r)) return "";
    const three = r.length >= 3;
    return `<svg class="ks" viewBox="0 0 26 24" width="26" height="24" role="img" aria-label="Pennsylvania Route ${r}"><path d="M2.5 1.5H23.5L21.8 5.2L24 7.4L19 22.5H7L2 7.4L4.2 5.2Z" fill="var(--surface)" stroke="var(--ink)" stroke-width="1.3" stroke-linejoin="round"/><text x="13" y="15.6" text-anchor="middle" font-family="Radio Canada, Arial, sans-serif" font-weight="700" font-size="${three ? 8.5 : 9.5}"${three ? ' style="font-stretch:85%"' : ""} fill="var(--ink)">${r}</text></svg>`;
  }
  const routes = (refs) => (refs || []).map((r) => shield(r) || `<span class="rt">${/^\d+$/.test(r) ? "Route " : ""}${esc(r)}</span>`).join("");
  const USPS = { Street: "St", Avenue: "Ave", Road: "Rd", Boulevard: "Blvd", Drive: "Dr", Lane: "Ln", Place: "Pl", Court: "Ct", Alley: "Aly" };
  const SUFFIX = /\b(Street|Avenue|Road|Boulevard|Drive|Lane|Place|Court|Alley)\b/g;
  function streetHead(n) {
    const m = String(n).match(/^(.*\S)\s+(Street|Avenue|Road|Boulevard|Drive|Lane|Place|Court|Alley)$/);
    return m ? `${esc(m[1])} <small>${USPS[m[2]]}</small>` : esc(n);
  }
  const shortAddr = (a) => String(a || "").split(",")[0].replace(SUFFIX, (w) => USPS[w]);
  const cap = (s) => String(s || "").replace(/^./, (c) => c.toUpperCase());
  const endStop = (s) => (/[.!?]$/.test(String(s).trim()) ? esc(String(s).trim()) : esc(String(s).trim()) + ".");
  const slug = (s) => String(s || "").toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  /* tel links: "724-339-7533 or 724-339-7534" -> [["724-339-7533", "tel:+17243397533"], …] */
  function tels(text) {
    const out = [], re = /\(?\b(\d{3})\)?[-. ]?(\d{3})[-. ](\d{4})\b|\b911\b/g;
    let m;
    while ((m = re.exec(String(text || "")))) out.push(m[0] === "911" ? ["911", "tel:911"] : [`${m[1]}-${m[2]}-${m[3]}`, `tel:+1${m[1]}${m[2]}${m[3]}`]);
    return out;
  }
  const telLink = (text, label = "Call {n}", cls = "tel") => {
    const t = tels(text)[0];
    return t ? `<a class="${cls}" href="${t[1]}">${esc(label.replace("{n}", t[0]))}</a>` : "";
  };

  /* ---------------- URL state (replaceState only: one Back always leaves the page) ---------------- */
  const qs = () => new URLSearchParams(location.search);
  function setQS(obj) {
    const p = qs();
    for (const [k, v] of Object.entries(obj)) {
      if (v == null || v === "" || v === false) p.delete(k); else p.set(k, v);
    }
    const s = p.toString().replace(/%2C/g, ",").replace(/%7E/g, "~");
    try { history.replaceState(history.state, "", location.pathname + (s ? "?" + s : "") + location.hash); } catch (e) { /* file:// or sandbox */ }
  }

  /* ---------------- theme ---------------- */
  const darkMQ = matchMedia("(prefers-color-scheme: dark)");
  const isDark = () => (doc.dataset.theme ? doc.dataset.theme === "dark" : darkMQ.matches);
  const themeHooks = [];
  function syncTheme() {
    const d = isDark();
    $$("[data-theme-toggle]").forEach((b) => {
      const long = !b.classList.contains("theme-btn");
      b.textContent = d ? (long ? "Light theme" : "Light") : (long ? "Dark theme" : "Dark");
      b.setAttribute("aria-label", d ? "Switch to light theme" : "Switch to dark theme");
    });
    /* themed pictures: <picture class="themed"><source media="(prefers-color-scheme: dark)" …> follow the chosen theme */
    $$("picture.themed source").forEach((s) => {
      if (!s.dataset.media) s.dataset.media = s.getAttribute("media") || "";
      if (!/prefers-color-scheme:\s*dark/.test(s.dataset.media)) return;
      s.setAttribute("media", doc.dataset.theme ? (d ? "all" : "not all") : s.dataset.media);
    });
  }
  function setTheme(t) {
    doc.dataset.theme = t;
    local.set("nk-theme", t);
    syncTheme();
    themeHooks.forEach((f) => { try { f(isDark()); } catch (e) { console.error(e); } });
  }
  document.addEventListener("click", (e) => {
    const b = e.target.closest("[data-theme-toggle]");
    if (b) setTheme(isDark() ? "light" : "dark");
  });
  darkMQ.addEventListener?.("change", () => { syncTheme(); themeHooks.forEach((f) => { try { f(isDark()); } catch (e) { console.error(e); } }); });

  /* ---------------- More menu: works without JS; with JS closes on Escape, outside click and navigation ---------------- */
  function wireMore() {
    const d = $("details.more");
    if (!d) return;
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && d.open) { d.open = false; d.querySelector("summary").focus(); } });
    document.addEventListener("click", (e) => { if (d.open && !d.contains(e.target)) d.open = false; });
    d.addEventListener("click", (e) => { if (e.target.closest("a")) d.open = false; });
    addEventListener("pageshow", () => { d.open = false; });
  }

  /* ---------------- wide tables fade at the right edge while they overflow ---------------- */
  function fadeWide(root = document) {
    $$(".dir-table-wrap", root).forEach((w) => {
      const upd = () => w.classList.toggle("fade", w.scrollWidth > w.clientWidth + 2 && w.scrollLeft + w.clientWidth < w.scrollWidth - 2);
      upd();
      if (w.dataset.fade) return;
      w.dataset.fade = 1;
      w.addEventListener("scroll", upd, { passive: true });
      if (window.ResizeObserver) {
        const ro = new ResizeObserver(upd);
        ro.observe(w);
        const t = w.querySelector("table");
        if (t) ro.observe(t);
      }
    });
  }

  /* ---------------- print: open every <details>, then put them back ---------------- */
  let printOpened = [];
  addEventListener("beforeprint", () => { printOpened = $$("details:not([open])"); printOpened.forEach((d) => { d.open = true; }); });
  addEventListener("afterprint", () => { printOpened.forEach((d) => { d.open = false; }); printOpened = []; });

  /* ---------------- my town, last visit, lost-pets badge ---------------- */
  const TOWNS = ["New Kensington", "Arnold", "Lower Burrell"];
  const town = () => { const t = local.get("nk-town"); return TOWNS.includes(t) ? t : null; };
  function setTown(t) {
    if (t && !TOWNS.includes(t)) return;
    if (t) local.set("nk-town", t); else local.del("nk-town");
    document.dispatchEvent(new CustomEvent("nk-town", { detail: t }));
  }
  /* order a list so my town comes first (never hides anything) */
  const townFirst = (list, key = (x) => x) => { const t = town(); return t ? [...list].sort((a, b) => (key(b) === t) - (key(a) === t)) : list; };
  /* the previous visit's start, fixed for this browser session */
  const prevVisit = (() => {
    let prev = session.get("nk-visit-prev");
    if (prev === null) {
      prev = local.get("nk-last-visit") || "";
      session.set("nk-visit-prev", prev);
      local.set("nk-last-visit", new Date().toISOString());
    }
    return prev || null;
  })();
  function setBadge(n) {
    const a = $('.secbar a[data-nav="lost-pets"]');
    if (!a) return;
    a.querySelector(".badge")?.remove();
    if (n > 0) {
      a.insertAdjacentHTML("beforeend", `<span class="badge" aria-hidden="true">${n > 9 ? "9+" : n}</span>`);
      a.setAttribute("aria-label", `Lost pets, ${n} new listing${n === 1 ? "" : "s"} since your last visit`);
    } else a.removeAttribute("aria-label");
  }

  /* ---------------- share and copy ---------------- */
  async function copy(text) {
    try { await navigator.clipboard.writeText(text); return true; } catch (e) { /* fall through */ }
    try {
      const t = Object.assign(document.createElement("textarea"), { value: text });
      t.setAttribute("readonly", ""); t.style.position = "fixed"; t.style.opacity = "0";
      document.body.appendChild(t); t.select();
      const ok = document.execCommand("copy"); t.remove(); return ok;
    } catch (e) { return false; }
  }
  /* resolves "shared" | "copied" | "failed" (a cancelled share sheet counts as shared) */
  async function share({ title, text, url }) {
    if (navigator.share) {
      try { await navigator.share({ title, text, url }); return "shared"; } catch (e) { if (e && e.name === "AbortError") return "shared"; }
    }
    return (await copy([text, url].filter(Boolean).join(" "))) ? "copied" : "failed";
  }
  /* absolute URL of a site path, for sharing */
  const abs = (path) => new URL(ROOT + String(path).replace(/^\//, ""), location.href).href;

  const NKS = window.NKS = {
    $, $$, esc, fmt, ROOT, url: (p) => ROOT + String(p).replace(/^\//, ""),
    local, session, getJSONKey,
    pubName, pub, credit, apDate, apDay, apLong, apTime, day, isoDay, today, daysFrom, relDay, ago, relabel,
    shield, routes, streetHead, shortAddr, cap, endStop, slug, tels, telLink,
    qs, setQS, isDark, onTheme: (f) => themeHooks.push(f), syncTheme, fadeWide,
    TOWNS, town, setTown, townFirst, prevVisit, setBadge, copy, share, abs,
    pages: {},
  };
  /* names older modules read */
  window.NKpub = Object.assign(pub, { pubName, credit });
  window.NKapDate = apDate;
  window.NKshield = shield;

  syncTheme();
  wireMore();
  relabel();
  fadeWide();
  void NKS;
})();

/* ==== js/20-crime.js ==== */
/* NK15068 — crime pages: /crime/, /crime/<town>/, /crime/blotter/, /crashes/.
   Everything is in the HTML; JS adds chart readouts, puts my town's short answer first, and runs the blotter filters. */
(function () {
  "use strict";
  const NKS = window.NKS;
  if (!NKS) return;
  const S = () => window.NKSafety;

  /* /crime/: my town's short answer first (reorders, never hides) */
  function orderAnswers() {
    const box = NKS.$("#answers");
    if (!box) return;
    const items = NKS.$$(".ans[data-town]", box);
    const ordered = NKS.townFirst(NKS.TOWNS, (t) => t);
    ordered.forEach((t) => { const el = items.find((x) => x.dataset.town === t); if (el) box.appendChild(el); });
    items.forEach((el) => el.classList.toggle("mine", el.dataset.town === NKS.town()));
  }

  NKS.pages.crime = () => {
    if (S()) S().enhanceCharts(document);
    orderAnswers();
    document.addEventListener("nk-town", orderAnswers);
  };
  NKS.pages["crime-dept"] = () => { if (S()) S().enhanceCharts(document); };
  NKS.pages.crashes = () => { if (S()) S().enhanceCharts(document); };
  NKS.pages.blotter = () => { if (S()) S().enhanceBlotter(NKS.$("#inc-block")); };
})();

/* ==== js/30-pets.js ==== */
/* NK15068 — lost & found pets pages: /lost-pets/ (board, Call now card, checklists, near-me sort), post/, flyer/
   and the deploy-only gh-N/ listing pages. Also keeps the home pets box and town-page lists live when their own page
   modules haven't wired them. Needs pets.js (window.NKPets); every element is looked up and guarded. */
(function () {
  "use strict";
  const S = window.NKS;
  if (!S) return;
  const { $, $$, esc } = S;
  const Pets = () => window.NKPets || null;
  const localToday = () => S.isoDay(new Date());
  const flash = (btn, text) => {
    const was = btn.textContent;
    btn.textContent = text;
    setTimeout(() => { btn.textContent = was; }, 1800);
  };
  const openTab = (url) => {
    const a = Object.assign(document.createElement("a"), { href: url, target: "_blank", rel: "noopener" });
    document.body.appendChild(a); a.click(); a.remove();
  };

  /* ================= /lost-pets/ ================= */
  S.pages["lost-pets"] = () => {
    const P = Pets(), main = $("#main"), board = $("#board"), list = $("#pets-list"), status = $("#pets-status");
    if (!P || !board || !list || !status) return;
    const d = board.dataset;
    const B = P.board;
    let spot = null; // {x, y, label}: in memory only; only the label is ever saved
    let mode = "lost";
    let firstDraw = true;

    /* ---- I lost / I found ---- */
    const RANK = {
      lost: { shelter: 0, police: 1, aco: 2, county: 3, warden: 4, vet: 5 },
      found: { police: 0, aco: 1, warden: 2, shelter: 3, county: 4, vet: 5 },
    };
    function setMode(m) {
      mode = m === "found" ? "found" : "lost";
      main.dataset.mode = mode;
      $$(".lp-toggles .seg").forEach((a) => a.setAttribute("aria-current", String(a.dataset.mode === mode)));
      $$("#call-now .cn-cap").forEach((p) => { p.hidden = p.dataset.for !== mode; });
      const ul = $("#call-now .cn-rows");
      if (ul) $$(".cn-row", ul).sort((a, b) => (RANK[mode][a.dataset.k] ?? 9) - (RANK[mode][b.dataset.k] ?? 9)).forEach((r) => ul.appendChild(r));
    }
    $$(".lp-toggles .seg").forEach((a) => a.addEventListener("click", (e) => { e.preventDefault(); setMode(a.dataset.mode); }));
    setMode(location.hash === "#found" ? "found" : "lost");
    addEventListener("hashchange", () => { if (location.hash === "#found" || location.hash === "#lost") setMode(location.hash.slice(1)); });

    /* ---- town picker: the town's police (and Lower Burrell's animal control) ---- */
    let town = "New Kensington";
    const picker = $("#call-now .picker");
    function pickTown(t, save) {
      if (!S.TOWNS.includes(t)) return;
      town = t;
      $$("button[data-town]", picker || document.createElement("div")).forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.town === t)));
      $$("#call-now .cn-row[data-town]").forEach((r) => { r.hidden = r.dataset.town !== t; });
      if (save) { S.setTown(t); S.setQS({ town: t }); }
    }
    if (picker) {
      picker.hidden = false;
      picker.addEventListener("click", (e) => { const b = e.target.closest("button[data-town]"); if (b) pickTown(b.dataset.town, true); });
    }
    const qTown = S.qs().get("town");
    pickTown(S.TOWNS.includes(qTown) ? qTown : S.town() || "New Kensington", false);

    /* ---- the owner's checklist, remembered on this device ---- */
    const loadChecks = () => { const v = S.getJSONKey("nk-checklist", {}); return v && typeof v === "object" && !Array.isArray(v) ? v : {}; };
    const checks = loadChecks();
    $$(".checklist input[data-check]").forEach((cb) => {
      cb.checked = !!checks[cb.dataset.check];
      cb.addEventListener("change", () => {
        const s = loadChecks();
        if (cb.checked) s[cb.dataset.check] = 1; else delete s[cb.dataset.check];
        S.local.set("nk-checklist", JSON.stringify(s));
      });
    });

    /* ---- board copy ---- */
    const telInline = () => (d.shelterTel ? `<a class="tel-inline" href="tel:+1${d.shelterTel.replace(/\D/g, "").slice(-10)}">${esc(d.shelterTel)}</a>` : "");
    const ext = (u, t) => (u ? `<a href="${esc(u)}" target="_blank" rel="noopener">${t}</a>` : t);
    function statusHTML() {
      const when = esc(P.checkedText(B.fetched)), whenStop = /\.$/.test(when) ? when : when + ".";
      switch (B.state) {
        case "listed":
          return B.mode === "db"
            ? "Listings posted here are shared with everyone who opens this page. Mark yours reunited when your pet is home."
            : `Listings posted by neighbors through the NK15068 form. Checked ${whenStop} A post comes down when its owner closes it.`;
        case "stale":
          return `The live board didn't answer. These are the listings as of ${whenStop}`;
        case "empty":
          return `No open listings on this board right now (checked ${when}). It only covers posts made here, so also check ${ext(d.pawboost, "PawBoost")} and ${ext(d.petco, "Petco Love Lost")}, and call the shelter, ${telInline()}.`;
        case "unknown":
          return `The board didn't load just now, so we can't tell you what's posted. ${ext(d.issues || P.ISSUES, "See the posts on GitHub ›")} or call ${esc(d.shelterName || "Animal Protectors")}, ${telInline()}.`;
        default:
          return "Checking the board…";
      }
    }
    const distOf = new Map();
    function sorted() {
      distOf.clear();
      const posts = B.posts.slice();
      if (!spot) return posts;
      posts.forEach((p) => distOf.set(p.id, P.distanceFrom(p, spot)));
      const m = (p) => (distOf.get(p.id) ? distOf.get(p.id).m : Infinity);
      return posts.sort((a, b) => m(a) - m(b));
    }
    function summaryHTML(posts) {
      if (B.state === "unknown") {
        return `The board didn't load just now. ${ext(d.issues || P.ISSUES, "See the posts on GitHub ›")}`;
      }
      if (B.state === "empty") {
        return `<a href="#board">The board: no open listings right now (checked ${esc(P.checkedText(B.fetched))}). <span class="bs-go">See the board ›</span></a>`;
      }
      const n = posts.length;
      const newest = posts.map((p) => (p.date || p.created || "").slice(0, 10)).filter(Boolean).sort().pop();
      let near = "";
      const first = posts[0], dist = first && distOf.get(first.id);
      if (spot && dist) {
        const how = dist.mi < 0.1 ? `${Math.max(50, Math.round(dist.m * 3.28084 / 50) * 50)} ft` : `${dist.mi.toFixed(1)} mi`;
        near = ` The nearest, a ${first.status} ${P.animalWord(first)}, is about ${how} from ${esc(P.shortStreet(spot.label))}.`;
      }
      return `<a href="#board">The board: ${n} open listing${n === 1 ? "" : "s"}${newest ? `, newest ${esc(P.shortDate(newest))}` : ""}.${near} <span class="bs-go">See the listings ›</span></a>`;
    }
    let dbBox = null;
    function draw() {
      if (B.state === "loading") {
        if (d.state === "nosnap") status.textContent = "Checking the board…";
        return;
      }
      d.state = B.state;
      status.innerHTML = statusHTML();
      const cnt = $("#board-count");
      if (cnt) cnt.textContent = B.state === "listed" || B.state === "stale" ? `${B.posts.length} open` : "";
      const chk = $("#board-checked");
      if (chk) chk.textContent = B.fetched && B.state !== "unknown" ? ` · Board checked ${P.checkedText(B.fetched)}` : "";
      const posts = sorted();
      $$(":scope > .listing:not(.listing-post)", list).forEach((n) => n.remove());
      const html = posts.map((p) => P.cardHTML(p, { dist: spot ? P.distText(distOf.get(p.id), spot.label) : "" })).join("")
        + (B.state === "empty" ? '<div class="listing listing-empty"><p>Nothing is posted on this board right now.</p></div>' : "");
      const postBox = $("#pets-post", list);
      if (postBox) postBox.insertAdjacentHTML("beforebegin", html); else list.insertAdjacentHTML("beforeend", html);
      if (B.mode === "db" && B.canPost && !dbBox && postBox) { dbBox = buildDbBox(); postBox.replaceWith(dbBox); }
      const sum = $("#board-sum");
      if (sum) { sum.innerHTML = summaryHTML(posts); sum.dataset.state = B.state; }
      S.relabel(list);
      if (firstDraw) {
        firstDraw = false;
        const h = location.hash.slice(1);
        const target = h && /^[\w-]+$/.test(h) ? document.getElementById(h) : null;
        if (target && target.classList.contains("listing")) { target.classList.add("is-target"); target.scrollIntoView({ block: "start" }); }
      }
      if (boardSeen) P.markSeen();
    }

    /* ---- share, reunite ---- */
    list.addEventListener("click", async (e) => {
      const sh = e.target.closest("[data-share]");
      if (sh) {
        const p = B.posts.find((x) => x.id === sh.dataset.share);
        if (!p) return;
        const r = await P.sharePost(p);
        if (r === "copied") flash(sh, "Link copied"); else if (r === "failed") flash(sh, "Couldn't share");
        return;
      }
      const r = e.target.closest("[data-reunite]");
      if (r) {
        r.disabled = true;
        try { await P.markReunited(r.dataset.reunite); } catch (err) { r.disabled = false; status.textContent = err.message || "That didn't save. Try again in a minute."; }
      }
    });

    /* ---- the listings count as seen once the board is on screen (clears the badge) ---- */
    let boardSeen = false;
    if ("IntersectionObserver" in window) {
      const io = new IntersectionObserver((es) => {
        if (es.some((x) => x.isIntersecting)) { boardSeen = true; if (B.known) P.markSeen(); io.disconnect(); }
      }, { threshold: 0.15 });
      io.observe(list);
    } else boardSeen = true;

    /* ---- your corner: typed, saved, or from this device's location ---- */
    const corner = $("#pets-corner"), input = $("#pets-near"), msg = $("#pets-corner-msg"), remember = $("#pets-remember");
    const say = (t) => { if (msg) msg.textContent = t; };
    function saveLabel(label) {
      if (remember && remember.checked && label) S.local.set("nk-corner", label); else S.local.del("nk-corner");
    }
    async function runCorner(text, opts = {}) {
      text = String(text || "").trim();
      if (!text) { spot = null; say(""); S.setQS({ near: null }); draw(); return; }
      say("Finding that corner…");
      try { await P.ensureIndex(); } catch (e) { say("The street map didn't load just now. Try again in a minute."); return; }
      const g = P.geocodeNear(text, town);
      if (!g) { spot = null; say("We couldn't find that corner. Try two street names, like 5th Avenue & 9th Street."); draw(); return; }
      spot = { x: g.x, y: g.y, label: g.label };
      say(`Sorted by distance from ${P.shortStreet(g.label)}.`);
      if (!opts.quiet) { S.setQS({ near: text }); saveLabel(text); }
      draw();
    }
    if (corner && input) {
      corner.hidden = false;
      $("#pets-sort").addEventListener("click", () => runCorner(input.value));
      input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); runCorner(input.value); } });
      if (remember) remember.addEventListener("change", () => saveLabel(input.value.trim()));
      const consent = $("#pets-consent");
      $("#pets-loc").addEventListener("click", () => {
        if (!navigator.geolocation) { say("This browser can't share a location. Type a corner instead."); return; }
        if (consent) consent.hidden = false;
        $("#pets-consent-go")?.focus();
      });
      $("#pets-consent-no")?.addEventListener("click", () => { consent.hidden = true; $("#pets-loc").focus(); });
      $("#pets-consent-go")?.addEventListener("click", () => {
        consent.hidden = true;
        say("Finding your nearest street…");
        navigator.geolocation.getCurrentPosition(async (pos) => {
          try {
            const [meta] = await Promise.all([P.loadMeta(), P.ensureIndex()]);
            const lon = pos.coords.longitude, lat = pos.coords.latitude;
            const x = (lon - meta.origin[0]) * meta.kx, y = (meta.origin[1] - lat) * meta.ky;
            const [x0, y0, x1, y1] = meta.bounds;
            if (x < x0 || x > x1 || y < y0 || y > y1) { say("You look to be outside 15068. Type a corner instead."); return; }
            const names = P.nearestStreets(x, y, 150);
            if (!names.length) { say("We couldn't find a street near you. Type a corner instead."); return; }
            const label = "Near " + names.map(P.shortStreet).join(" & ");
            input.value = label;
            spot = { x, y, label: names.join(" & ") };
            say(`Sorted by distance from ${P.shortStreet(spot.label)}.`);
            saveLabel(label);
            draw();
          } catch (e) { say("The street map didn't load just now. Type a corner instead."); }
        }, () => say("Your location isn't available. Type a corner instead."), { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 });
      });
      const qNear = S.qs().get("near"), saved = S.local.get("nk-corner");
      if (saved && remember) remember.checked = true;
      const start = qNear || saved;
      if (start) { input.value = start; runCorner(start, { quiet: !qNear }); }
    }

    /* ---- in the artifact preview the board is a shared store: post right here ---- */
    function buildDbBox() {
      const box = document.createElement("div");
      box.className = "listing listing-post";
      box.id = "pets-post";
      const today = localToday(), L = P.LIMITS;
      box.innerHTML = `<h3>Place a free listing</h3>
        <p>Lost, found or spotted a pet in 15068? Post it here and everyone who opens this page sees it.</p>
        <button type="button" class="btn-line" id="pets-open" aria-expanded="false" aria-controls="pets-form">Write a listing</button>
        <form id="pets-form" class="petform" hidden>
          <label>Lost, found or spotted?<select name="status" required><option value="lost">Lost</option><option value="found">Found</option><option value="spotted">Spotted</option></select></label>
          <label>Animal<select name="animal"><option value="dog">Dog</option><option value="cat">Cat</option><option value="other">Other</option></select></label>
          <label>Pet's name (if known)<input name="name" maxlength="${L.name}" autocomplete="off"></label>
          <label>Description<textarea name="desc" maxlength="${L.desc}" required placeholder="Breed, color, size, collar or tags"></textarea></label>
          <label>Last seen near<input name="near" maxlength="${L.near}" required placeholder="Fifth Avenue &amp; 9th Street" autocomplete="off"></label>
          <label>Town<select name="town">${P.TOWNS.map((t) => `<option>${esc(t)}</option>`).join("")}</select></label>
          <label>Date<input type="date" name="date" required value="${today}" max="${today}"></label>
          <label>How to reach you (public)<input name="contact" maxlength="${L.contact}" required autocomplete="off"></label>
          <p class="fine">Everyone who can open this page sees the listing. Give a street and cross street rather than a house number; house numbers are removed.</p>
          <button type="submit" class="btn-line">Post the listing</button>
          <p class="form-msg" role="status"></p>
        </form>`;
      const form = box.querySelector("form"), openBtn = box.querySelector("#pets-open"), fmsg = box.querySelector(".form-msg");
      openBtn.onclick = () => { form.hidden = !form.hidden; openBtn.setAttribute("aria-expanded", String(!form.hidden)); if (!form.hidden) form.status.focus(); };
      form.onsubmit = async (e) => {
        e.preventDefault();
        const f = new FormData(form), post = {};
        for (const k of ["status", "animal", "name", "desc", "near", "town", "date", "contact"]) post[k] = String(f.get(k) || "").trim().slice(0, L[k] || 40);
        post.near = P.cleanNear(post.near);
        try {
          await P.ensureIndex();
          const g = P.geocodeNear(post.near, post.town);
          if (g) Object.assign(post, { x: Math.round(g.x), y: Math.round(g.y), prec: g.prec, placeLabel: g.label });
        } catch (err) { /* posts without a pin are fine */ }
        fmsg.textContent = "Posting…";
        try {
          await P.addPost(post);
          form.reset(); form.date.value = form.date.max = localToday();
          fmsg.textContent = typeof post.x === "number" ? "Posted. It's on the board and the map." : "Posted. That street wasn't found on the map, so the listing has no pin.";
        } catch (err) {
          fmsg.textContent = err.message || "It didn't post. Try again in a minute.";
          if (B.readOnly) form.querySelectorAll("input, select, textarea, button").forEach((el) => { el.disabled = true; });
        }
      };
      return box;
    }

    P.loadBoard({ ui: { onChange: draw } });
    draw();
  };

  /* ================= /lost-pets/post/ ================= */
  S.pages["lost-pets-post"] = () => {
    const P = Pets(), form = $("#post-form");
    if (!P || !form) return;
    const f = (id) => $("#" + id);
    const msg = (t) => { const m = f("post-msg"); if (m) m.textContent = t; };
    const today = localToday();
    const date = f("f-date");
    if (date) { date.max = today; if (!date.value) date.value = today; }
    /* coming back from the flyer: the draft is still in this tab */
    let old = null;
    try { old = JSON.parse(S.session.get("nk-flyer-draft") || "null"); } catch (e) { old = null; }
    if (old && typeof old === "object") {
      const set = (id, v) => { if (f(id) && v) f(id).value = v; };
      set("f-status", P.STATUS[old.status]); set("f-animal", old.animal ? old.animal[0].toUpperCase() + old.animal.slice(1) : "");
      set("f-name", old.name); set("f-desc", old.desc); set("f-near", old.near); set("f-town", old.town);
      set("f-date", old.date); set("f-contact", old.contact);
    }
    f("f-near")?.addEventListener("change", () => {
      const el = f("f-near"), v = P.cleanNear(el.value);
      if (v !== el.value.trim()) { el.value = v; msg("House numbers are removed. The street and cross street are what gets posted."); }
    });
    const draft = () => ({
      status: f("f-status").value.toLowerCase(), animal: f("f-animal").value.toLowerCase(), name: f("f-name").value.trim(),
      desc: f("f-desc").value.trim(), near: P.cleanNear(f("f-near").value), town: f("f-town").value, date: f("f-date").value,
      contact: f("f-contact").value.trim(),
    });
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      if (!form.reportValidity()) return;
      openTab(P.issueUrl(draft()));
      msg("GitHub's form opened in a new tab with your details typed in. Check them, add a photo if you like, and submit.");
    });

    /* photo for the flyer only: kept in this tab, shrunk if it's big */
    async function photoURL() {
      const file = f("f-photo")?.files?.[0];
      if (!file || !/^image\//.test(file.type)) return "";
      const read = (blob) => new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(blob); });
      if (file.size < 1.5e6) return read(file);
      try {
        const bmp = await createImageBitmap(file);
        const k = Math.min(1, 1400 / Math.max(bmp.width, bmp.height));
        const c = Object.assign(document.createElement("canvas"), { width: Math.round(bmp.width * k), height: Math.round(bmp.height * k) });
        c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
        const url = c.toDataURL("image/jpeg", 0.85);
        return url.length < 2e6 ? url : "";
      } catch (e) { return ""; }
    }
    const fl = f("post-flyer");
    if (fl) {
      fl.hidden = false;
      fl.addEventListener("click", async () => {
        if (!form.reportValidity()) return;
        const d = draft();
        d.photo = await photoURL();
        if (!S.session.set("nk-flyer-draft", JSON.stringify(d))) {
          delete d.photo;
          S.session.set("nk-flyer-draft", JSON.stringify(d));
        }
        location.href = S.url("lost-pets/flyer/");
      });
    }
    const sh = f("post-share");
    if (sh) {
      sh.hidden = false;
      sh.addEventListener("click", async () => {
        if (!form.reportValidity()) return;
        const d = draft();
        const r = await S.share({ title: P.headline(d), text: P.shareText(d), url: S.abs("lost-pets/") });
        if (r === "copied") flash(sh, "Copied"); else if (r === "failed") flash(sh, "Couldn't share");
      });
    }
    const mail = f("post-mail");
    if (mail && form.dataset.email) {
      mail.addEventListener("click", (e) => {
        if (!form.reportValidity()) { e.preventDefault(); return; }
        mail.href = P.mailtoUrl(draft(), form.dataset.email);
      });
    }
  };

  /* ================= /lost-pets/flyer/ ================= */
  S.pages["lost-pets-flyer"] = async () => {
    const P = Pets(), note = $("#fl-note");
    const pb = $("#fl-print");
    if (pb) pb.addEventListener("click", () => window.print());
    const post_ = S.url("lost-pets/post/"), board_ = S.url("lost-pets/");
    if (note) note.innerHTML = `There&rsquo;s no pet on this flyer yet. Fill in the <a href="${esc(post_)}">Post a pet</a> form and tap Make a flyer, or tap Flyer on a listing on <a href="${esc(board_)}#board">the board</a>.`;
    const back = $("#fl-back");
    if (back) {
      let same = false;
      try { same = !!document.referrer && new URL(document.referrer).origin === location.origin; } catch (e) { same = false; }
      if (same && history.length > 1) back.addEventListener("click", (e) => { e.preventDefault(); history.back(); });
    }
    if (!P) return;
    const id = S.qs().get("pet");
    let post = null, photo = "";
    if (id) {
      if (note) note.textContent = "Getting that listing from the board…";
      await P.loadBoard();
      post = P.board.posts.find((p) => p.id === id) || null;
      if (!post) {
        if (note) note.textContent = P.board.state === "unknown"
          ? "The board didn't load just now, so the flyer can't be filled in. Try again in a minute."
          : "That listing isn't on the board now. Its owner may have closed it.";
        return;
      }
      photo = post.photo || "";
    } else {
      let dr = null;
      try { dr = JSON.parse(S.session.get("nk-flyer-draft") || "null"); } catch (e) { dr = null; }
      if (dr && typeof dr === "object") {
        post = P.sanitize({ ...dr, id: "draft" }, "board");
        photo = typeof dr.photo === "string" && /^data:image\//.test(dr.photo) ? dr.photo : "";
      }
      if (!post) return;
    }
    const animal = P.animalWord(post);
    const h = `${P.STATUS[post.status].toUpperCase()} ${animal.toUpperCase()}`;
    const q = post.status === "lost" ? (post.name ? `Have you seen ${post.name}?` : `Have you seen this ${animal}?`)
      : post.status === "found" ? `Is this your ${animal}?` : (post.name ? `Is this ${post.name}?` : `Have you lost this ${animal}?`);
    const day = post.date || String(post.created || "").slice(0, 10);
    const w = P.where(post);
    const seen = w ? `${P.nearLine({ ...post, prec: null }).replace(/ \(no cross street given\)$/, "")}${day ? ", " + S.apLong(day, false) : ""}` : "";
    let contact = post.contact || "";
    if (!contact || /^comment\b/i.test(contact)) {
      const u = new URL(P.shareUrl(post), location.href);
      contact = `Details: ${u.host}${u.pathname}${u.hash}`;
    }
    const set = (sel, t) => { const el = $(sel); if (el) el.textContent = t; };
    /* phone numbers never break across lines on paper */
    const nobreak = (t) => esc(t).replace(/\(?\b\d{3}\)?[-. ]?\d{3}[-. ]\d{4}\b/g, '<span class="nw">$&</span>');
    set("#fl-h", h); set("#fl-q", q); set("#fl-desc", post.desc || ""); set("#fl-seen", seen);
    const ce = $("#fl-contact");
    if (ce) ce.innerHTML = nobreak(contact);
    const img = $("#fl-photo");
    if (img && photo) { img.src = photo; img.alt = post.name ? `Photo of ${post.name}` : `Photo of the ${animal}`; img.hidden = false; }
    const tabs = $("#fl-tabs");
    if (tabs) {
      const t = `${post.name || cap(animal)} · ${contact.replace(/^Details: /, "")}`;
      tabs.innerHTML = Array.from({ length: 8 }, () => `<li>${nobreak(t)}</li>`).join("");
    }
    const flyer = $("#flyer");
    if (flyer) flyer.dataset.status = post.status;
    if (note) note.hidden = true;
    if (pb) pb.hidden = false;
    $(".flyer-page")?.classList.add("filled");
    document.title = `${h}${post.name ? ": " + post.name : ""} · NK15068`;
  };
  const cap = (s) => String(s || "").replace(/^./, (c) => c.toUpperCase());

  /* ================= /lost-pets/gh-N/ ================= */
  S.pages["lost-pets-listing"] = () => {
    const P = Pets();
    if (!P) return;
    P.loadBoard();
    $$("[data-share]").forEach((b) => {
      b.hidden = false;
      b.addEventListener("click", async () => {
        await P.loadBoard();
        const p = P.board.posts.find((x) => x.id === b.dataset.share);
        const url = location.href.split(/[?#]/)[0];
        const r = p ? await S.share({ title: P.headline(p), text: P.shareText(p), url })
          : await S.share({ title: document.title, text: ($("h1") || {}).textContent || "", url });
        if (r === "copied") flash(b, "Link copied"); else if (r === "failed") flash(b, "Couldn't share");
      });
    });
  };

  /* ================= home box and town lists, if their page modules didn't wire them ================= */
  function wire() {
    const P = Pets();
    if (!P) return;
    const box = $("#pets-box");
    if (box) P.renderHomeBox(box);
    $$("[data-pets-town]").forEach((el) => P.renderTownList(el, el.dataset.petsTown));
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", wire); else setTimeout(wire, 0);
})();

/* ==== js/40-home.js ==== */
/* NK15068 — front page, phone numbers and calendar (owner: home pages).
   The HTML already holds every row; this only drops calendar rows that have passed on this device, puts my town
   first, writes the since-your-last-visit line, and builds .ics files on the device. */
(function () {
  "use strict";
  const S = window.NKS;
  if (!S) return;
  const { $, $$, esc } = S;
  const todayISO = () => S.isoDay(S.today());

  /* "Sept. 10" this year, "Sept. 10, 2025" otherwise */
  const shortDate = (iso) => {
    const s = S.apDate(iso);
    return iso.slice(0, 4) === String(new Date().getFullYear()) ? s.replace(/, \d{4}$/, "") : s;
  };

  /* ================= front page ================= */

  /* drop rows dated before today and top the list back up to 3 from the hidden <template id="cal-more"> */
  function calRows() {
    const list = $("#cal-rows");
    if (!list) return;
    const t = todayISO();
    $$(".cal-row", list).forEach((li) => { if (li.dataset.date < t) li.remove(); });
    const tpl = $("#cal-more");
    const spare = tpl && tpl.content ? [...tpl.content.querySelectorAll(".cal-row")] : [];
    for (const li of spare) {
      if ($$(".cal-row", list).length >= 3) break;
      if (li.dataset.date >= t && !$$(".cal-row", list).some((r) => r.dataset.id === li.dataset.id)) list.appendChild(document.importNode(li, true));
    }
    S.relabel(list);
  }

  /* my town's police button first, marked .mine (reorders, never hides) */
  function policeOrder() {
    const box = $("#nums-police");
    if (!box) return;
    const btns = $$("a.tel[data-town]", box), t = S.town();
    S.townFirst(S.TOWNS).forEach((name) => { const b = btns.find((x) => x.dataset.town === name); if (b) box.appendChild(b); });
    btns.forEach((b) => b.classList.toggle("mine", !!t && b.dataset.town === t));
  }

  /* "Since your last visit on Sept. 10: 1 new lost-pet listing · 2 data updates" — only after a day or more away */
  function sinceLine() {
    const el = $("#since");
    const prev = S.prevVisit;
    if (!el || !prev) return;
    const t = Date.parse(prev);
    if (!Number.isFinite(t) || Date.now() - t < 864e5) return;
    let changes = [];
    try { changes = JSON.parse(($("#changes") || {}).textContent || "[]"); } catch (e) { changes = []; }
    const prevDay = S.isoDay(new Date(t));
    const fresh = (Array.isArray(changes) ? changes : []).filter((c) => c && String(c.date) > prevDay);
    const draw = () => {
      const P = window.NKPets;
      const pets = P && P.board && P.board.known ? P.newSince(prev) : 0;
      const parts = [];
      if (pets > 0) parts.push(`<a href="${esc(S.url("lost-pets/"))}#board">${pets} new lost-pet listing${pets === 1 ? "" : "s"}</a>`);
      if (fresh.length) parts.push(`<a href="${esc(S.url("whats-new/"))}">${fresh.length === 1 ? "a data update" : `${fresh.length} data updates`} ›</a>`);
      if (!parts.length) { el.hidden = true; return; }
      el.innerHTML = `Since your last visit on ${esc(shortDate(prevDay))}: ${parts.join(" · ")}`;
      el.hidden = false;
    };
    draw();
    if (window.NKPets && typeof window.NKPets.loadBoard === "function") {
      try { window.NKPets.loadBoard({ ui: draw }); } catch (e) { console.error(e); }
    }
  }

  S.pages.home = () => {
    calRows();
    policeOrder();
    document.addEventListener("nk-town", policeOrder);
    sinceLine();
  };

  /* ================= /numbers/ ================= */
  S.pages.numbers = () => {
    const cards = $("#ncards"), tools = $("#ntools");
    if (!cards || !tools) return;
    const order0 = $$(".ncard", cards);
    const btns = $$(".picker button", tools), remember = $("#n-remember");
    let sel = S.town() || "";
    function apply() {
      btns.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.town === sel)));
      const first = order0.filter((c) => sel && c.dataset.town === sel);
      [...first, ...order0.filter((c) => !first.includes(c))].forEach((c) => cards.appendChild(c));
      if (!remember) return;
      const saved = S.town();
      remember.hidden = !sel;
      remember.disabled = !!sel && saved === sel;
      remember.textContent = remember.disabled ? "Remembered on this device" : "Remember my town";
    }
    btns.forEach((b) => b.addEventListener("click", () => { sel = b.dataset.town || ""; apply(); }));
    if (remember) remember.addEventListener("click", () => { if (sel) { S.setTown(sel); apply(); } });
    tools.hidden = false;
    apply();
    const pr = $("#n-print");
    if (pr) { pr.hidden = false; pr.addEventListener("click", () => window.print()); }
  };

  /* ================= /calendar/ ================= */
  const icsText = (s) => String(s || "").replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
  /* fold at 75 octets (continuation lines start with a space) */
  function fold(line) {
    const enc = new TextEncoder();
    let out = "", cur = "", n = 0, limit = 75;
    for (const ch of line) {
      const b = enc.encode(ch).length;
      if (n + b > limit) { out += cur + "\r\n "; cur = ""; n = 0; limit = 74; }
      cur += ch; n += b;
    }
    return out + cur;
  }
  function ics(d) {
    const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
    const url = location.href.split("#")[0].split("?")[0] + "#" + d.id;
    const lines = [
      "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//NK15068//Calendar//EN", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
      "BEGIN:VEVENT", `UID:${d.id}-${d.s || d.d}@nk15068.com`, `DTSTAMP:${stamp}`,
      d.s ? `DTSTART:${d.s}` : `DTSTART;VALUE=DATE:${d.d}`,
      d.s ? `DTEND:${d.e}` : `DTEND;VALUE=DATE:${d.e}`,
      `SUMMARY:${icsText(d.t)}`,
      d.w ? `LOCATION:${icsText(d.w)}` : "",
      d.x ? `DESCRIPTION:${icsText(d.x)}` : "",
      `URL:${url}`, "END:VEVENT", "END:VCALENDAR",
    ].filter(Boolean);
    return lines.map(fold).join("\r\n") + "\r\n";
  }
  function download(d) {
    const blob = new Blob([ics(d)], { type: "text/calendar;charset=utf-8" });
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(blob), download: `${d.id}.ics` });
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
  }

  S.pages.calendar = () => {
    const t = todayISO();
    $$(".cal-item[data-date]").forEach((it) => { if (it.dataset.date < t) it.hidden = true; });
    $$(".cal-group").forEach((g) => {
      const items = $$(".cal-item", g);
      if (items.length && items.every((i) => i.hidden)) g.hidden = true;
    });
    $$("button[data-ics]").forEach((b) => {
      let d = null;
      try { d = JSON.parse(b.dataset.ics); } catch (e) { d = null; }
      if (!d || !d.id || !(d.s || d.d)) return;
      b.hidden = false;
      b.addEventListener("click", () => download(d));
    });
  };
})();

/* ==== js/50-towns.js ==== */
/* NK15068 — towns hub, town pages, news, history, poster and privacy (owner: towns pages).
   Every page's text is already in the HTML; this adds town chips, "New to you", My town, the street poster,
   PNG export and "Forget my settings". */
(function () {
  "use strict";
  const S = window.NKS;
  if (!S) return;
  const { $, $$, esc } = S;

  /* a link to an item inside a closed <details> (news/#n-…) opens it */
  function openTarget() {
    let id = "";
    try { id = decodeURIComponent(location.hash.slice(1)); } catch (e) { return; }
    const el = id && document.getElementById(id);
    if (!el) return;
    const d = el.closest("details");
    if (d && !d.open) { d.open = true; el.scrollIntoView(); }
  }
  addEventListener("hashchange", openTarget);

  /* town chips: All · New Kensington · Arnold · Lower Burrell, filtering items by data-towns="A|B" */
  function wireChips(what, items, noun, after) {
    const row = $(`[data-chips="${what}"]`);
    if (!row || !items.length) return;
    row.hidden = false;
    const btns = $$("button[data-town]", row), count = $(".chip-count", row);
    function apply(town) {
      btns.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.town === town)));
      let n = 0;
      items.forEach((el) => {
        const ok = !town || (el.dataset.towns || "").split("|").includes(town);
        el.hidden = !ok;
        if (ok) n++;
      });
      count.textContent = town ? `${n} of ${items.length} ${noun} mention ${town}.` : "";
      if (after) after(town, n);
    }
    row.addEventListener("click", (e) => {
      const b = e.target.closest("button[data-town]");
      if (b) apply(b.dataset.town);
    });
  }

  /* ================= /towns/ : my town's card first ================= */
  S.pages.towns = () => {
    const t = S.town(), grid = $("#towns-grid");
    if (!t || !grid) return;
    const card = $$(".tw-card", grid).find((c) => c.dataset.town === t);
    if (card) { grid.prepend(card); card.classList.add("mine"); }
  };

  /* ================= /towns/<town>/ ================= */
  S.pages.town = () => {
    const btn = $("[data-my-town]"), note = $(".cc-mine-note");
    if (btn) {
      const t = btn.dataset.myTown;
      const sync = () => {
        const mine = S.town() === t;
        btn.setAttribute("aria-pressed", String(mine));
        btn.textContent = mine ? `${t} is my town` : `Make ${t} my town`;
      };
      btn.hidden = false;
      sync();
      btn.addEventListener("click", () => {
        const was = S.town() === t;
        S.setTown(was ? null : t);
        sync();
        if (note) {
          note.hidden = false;
          note.textContent = was ? "Done. No town is saved on this device now."
            : `Saved on this device. ${t} now comes first on the front page, Phone numbers, Lost pets and Crime.`;
        }
      });
      document.addEventListener("nk-town", sync);
    }
    const P = window.NKPets;
    if (P && P.renderTownList) $$("[data-pets-town]").forEach((el) => P.renderTownList(el, el.dataset.petsTown));
    openTarget();
  };

  /* ================= /news/ ================= */
  S.pages.news = () => {
    const arts = $$("article.brief");
    /* "New to you": briefs this device hasn't listed before (the first visit marks nothing) */
    const seen = S.getJSONKey("nk-seen-news", null);
    if (Array.isArray(seen)) {
      const set = new Set(seen);
      arts.forEach((a) => { if (!set.has(a.id)) { const tag = $(".new-tag", a); if (tag) tag.hidden = false; } });
    }
    const ids = arts.map((a) => a.id);
    const keep = [...new Set([...(Array.isArray(seen) ? seen : []).filter((i) => typeof i === "string"), ...ids])].slice(-300);
    S.local.set("nk-seen-news", JSON.stringify(keep));
    const earlier = $("#earlier"), none = $("#news-none");
    wireChips("news", arts, "briefs", (town, n) => {
      if (earlier) earlier.hidden = !!town && !$$(".brief", earlier).some((a) => !a.hidden);
      if (none) none.hidden = n > 0;
    });
    openTarget();
  };

  /* ================= /history/ ================= */
  S.pages.history = () => {
    const items = $$(".era .tl-item"), none = $("#tl-none");
    wireChips("history", items, "events", (town, n) => {
      $$(".era").forEach((sec) => { sec.hidden = !!town && !$$(".tl-item", sec).some((i) => !i.hidden); });
      if (none) none.hidden = n > 0;
    });
    openTarget();
  };

  /* ================= /privacy/ : Forget my settings ================= */
  S.pages.privacy = () => {
    const b = $("#forget"), msg = $("#forget-msg");
    if (!b) return;
    b.hidden = false;
    b.addEventListener("click", () => {
      [S.local, S.session].forEach((st) => st.keys().filter((k) => k.startsWith("nk-")).forEach((k) => st.del(k)));
      delete document.documentElement.dataset.theme;
      S.syncTheme();
      S.setBadge(0);
      if (msg) msg.textContent = "Done. Your settings on this device are cleared.";
    });
  };

  /* ================= /poster/ ================= */
  const getJSON = (p) => fetch(S.url(p)).then((r) => (r.ok ? r.json() : Promise.reject(new Error(p + " " + r.status))));
  const getText = (u) => fetch(u).then((r) => (r.ok ? r.text() : Promise.reject(new Error(u + " " + r.status))));

  function download(blob, name) {
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(blob), download: name });
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  }

  /* rasterize an SVG document to PNG on this device (3600 x 4800, smaller if the browser's canvas limit is lower) */
  async function savePNG(svgText, name, msg) {
    if (msg) msg.textContent = "Drawing the PNG…";
    const url = URL.createObjectURL(new Blob([svgText], { type: "image/svg+xml" }));
    try {
      const img = new Image();
      await new Promise((res, rej) => { img.onload = res; img.onerror = () => rej(new Error("svg")); img.src = url; });
      for (const [w, h] of [[3600, 4800], [3000, 4000], [2400, 3200]]) {
        let c = document.createElement("canvas");
        c.width = w; c.height = h;
        const ctx = c.getContext("2d");
        if (!ctx) continue;
        ctx.drawImage(img, 0, 0, w, h);
        const out = await new Promise((r) => { try { c.toBlob(r, "image/png"); } catch (e) { r(null); } });
        c.width = c.height = 0; c = null;
        if (!out) continue;
        download(out, name);
        if (msg) msg.textContent = w === 3600 ? "Saved a 3600 × 4800 PNG." : `Saved a ${w} × ${h} PNG, the largest this browser can make.`;
        return;
      }
      if (msg) msg.textContent = "This browser couldn't make the PNG. Download the SVG instead; it prints at any size.";
    } catch (e) {
      if (msg) msg.textContent = "This browser couldn't make the PNG. Download the SVG instead; it prints at any size.";
    } finally {
      URL.revokeObjectURL(url);
    }
  }

  /* street names: the same key pets.js and nkpages.fmt use ('Fifth Avenue' and '5th Ave' -> {core: '5', type: 'ave'}) */
  const ORD = { first: "1", second: "2", third: "3", fourth: "4", fifth: "5", sixth: "6", seventh: "7", eighth: "8", ninth: "9", tenth: "10",
    eleventh: "11", twelfth: "12", thirteenth: "13", fourteenth: "14", fifteenth: "15", sixteenth: "16", seventeenth: "17", eighteenth: "18",
    nineteenth: "19", twentieth: "20" };
  const TYPES = { street: "st", st: "st", avenue: "ave", ave: "ave", av: "ave", road: "rd", rd: "rd", drive: "dr", dr: "dr", boulevard: "blvd",
    blvd: "blvd", lane: "ln", ln: "ln", court: "ct", ct: "ct", place: "pl", pl: "pl", way: "way", alley: "aly", aly: "aly", terrace: "ter",
    ter: "ter", highway: "hwy", hwy: "hwy", pike: "pike", circle: "cir", cir: "cir" };
  function streetKey(name) {
    if (window.NKPets && window.NKPets.streetKey) return window.NKPets.streetKey(name);
    let t = String(name || "").toLowerCase().replace(/[.,#']/g, " ").split(/\s+/).filter(Boolean);
    t = t.map((w) => ORD[w] || w.replace(/^(\d+)(st|nd|rd|th)$/, "$1"));
    let type = null;
    while (t.length && TYPES[t[t.length - 1]]) { type = type || TYPES[t[t.length - 1]]; t.pop(); }
    if (t.length > 1 && /^(n|s|e|w|north|south|east|west)$/.test(t[0])) t.shift();
    const core = t.join(" ");
    return core ? { core, type } : null;
  }
  /* the streets a query could mean, best first: an exact name, then the same street key (Fifth Ave = 5th Avenue),
     then names that start with or contain the text */
  function findStreets(q, streets) {
    const s = q.trim().toLowerCase();
    if (!s) return [];
    const big = (a, b) => (b.a || 0) - (a.a || 0) || b.m - a.m;
    const out = [], add = (list) => list.sort(big).forEach((x) => { if (!out.includes(x)) out.push(x); });
    add(streets.filter((x) => x.n.toLowerCase() === s));
    const k = streetKey(q);
    if (k) add(streets.filter((x) => { const kk = streetKey(x.n); return kk && kk.core === k.core && (!k.type || kk.type === k.type); }));
    add(streets.filter((x) => x.n.toLowerCase().startsWith(s)));
    add(streets.filter((x) => x.n.toLowerCase().includes(s)));
    return out;
  }

  let world = null;
  function loadWorld() {
    if (!world) {
      world = Promise.all([getJSON("data/meta.json"), getJSON("data/roads.json"), getJSON("data/streets.json")]).then(([meta, roads, streets]) => {
        const q = meta.q;
        const lines = roads.r.map(([rank, ni, , c]) => ({ rank, n: ni >= 0 ? roads.names[ni] : null, c }));
        return { meta, q, lines, streets };
      });
      world.catch(() => { world = null; });
    }
    return world;
  }
  const dec = (c, q) => { const out = []; let x = 0, y = 0; for (let i = 0; i + 1 < c.length; i += 2) { x += c[i]; y += c[i + 1]; out.push([x / q, y / q]); } return out; };
  const TOWN_NAME = { Allegheny: "Allegheny Township" };
  const niceLen = (m) => { const e = 10 ** Math.floor(Math.log10(Math.max(m, 1))); return Math.max(...[1, 2, 5].map((f) => f * e).filter((v) => v <= m)); };
  const r1 = (v) => Math.round(v * 10) / 10;

  /* the poster cropped to one street: viewBox around it, line weights kept the same on paper, the street in the
     highlight colour at 3x its width, and its name and towns in the title */
  function streetPoster(svgText, street, W) {
    const doc = new DOMParser().parseFromString(svgText, "image/svg+xml");
    const root = doc.documentElement, map = doc.getElementById("map");
    if (!map || root.nodeName !== "svg") throw new Error("poster");
    const mine = W.lines.filter((l) => l.n === street.n).map((l) => ({ rank: l.rank, pts: dec(l.c, W.q) }));
    if (!mine.length) return null;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    mine.forEach((l) => l.pts.forEach(([x, y]) => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }));
    const pad = 400, mw = +map.getAttribute("width"), mh = +map.getAttribute("height");
    let w = x1 - x0 + 2 * pad, h = y1 - y0 + 2 * pad;
    const k = Math.max(w / mw, h / mh);
    w = mw * k; h = mh * k;
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    map.setAttribute("viewBox", `${Math.round(cx - w / 2)} ${Math.round(cy - h / 2)} ${Math.round(w)} ${Math.round(h)}`);
    /* the same line weights on paper, a touch bolder so a few streets don't look faint */
    const kk = k * 1.25;
    $$("[data-w]", map).forEach((el) => el.setAttribute("stroke-width", r1(+el.dataset.w * kk)));
    const zl = doc.getElementById("zipline");
    if (zl && zl.dataset.dash) zl.setAttribute("stroke-dasharray", zl.dataset.dash.split(" ").map((v) => Math.round(v * kk)).join(" "));
    $$("text[data-fs]", map).forEach((t) => {
      const fs = +t.dataset.fs * k;
      t.setAttribute("font-size", r1(fs));
      t.setAttribute("stroke-width", r1(fs * 0.24));
      t.setAttribute("letter-spacing", r1(fs * 0.14));
    });
    /* the street itself, over the roads and under the town names */
    const NS = "http://www.w3.org/2000/svg";
    const top = Math.min(...mine.map((l) => l.rank));
    const base = { 0: 7, 1: 6.2, 2: 5.2, 3: 3.8, 4: 2.8, 5: 2.1, 6: 1.3, 7: 1.1 }[top] || 2;
    const hi = doc.createElementNS(NS, "path");
    hi.setAttribute("d", mine.map((l) => "M" + l.pts.map(([x, y]) => `${Math.round(x)} ${Math.round(y)}`).join("L")).join(""));
    hi.setAttribute("fill", "none");
    hi.setAttribute("stroke", root.dataset.focus || "#0b63c4");
    hi.setAttribute("stroke-width", r1(Math.max(base * 3, 6) * kk));
    hi.setAttribute("stroke-linecap", "round");
    hi.setAttribute("stroke-linejoin", "round");
    const towns = doc.getElementById("towns");
    map.insertBefore(hi, towns);
    /* title, subtitle, scale */
    const names = (street.t || []).map((t) => TOWN_NAME[t] || t);
    const title = `${street.n}${names.length ? " · " + names.join(" · ") : ""}, PA 15068`.toUpperCase();
    const tt = doc.getElementById("title");
    if (tt) {
      const fs = Math.min(118, 3300 / (title.length * 0.72));
      tt.textContent = title;
      tt.setAttribute("font-size", r1(fs));
      tt.setAttribute("letter-spacing", r1(fs * 0.05));
    }
    const st = doc.getElementById("subtitle"), m = W.meta;
    if (st) {
      const lon = m.origin[0] + cx / m.kx, lat = m.origin[1] - cy / m.ky;
      st.textContent = `ZIP 15068 · ${Math.abs(lat).toFixed(2)}° N, ${Math.abs(lon).toFixed(2)}° W`;
    }
    const sc = doc.getElementById("scale");
    if (sc) {
      const ink = root.dataset.ink || "#191a1b", y = +sc.querySelector("rect").getAttribute("y");
      const len = niceLen(520 * k), L = len / k, sx = 1800 - L / 2;
      const lab = len >= 1000 ? `${len / 1000} km` : `${len} m`, half = len >= 1000 ? `${len / 2000}` : `${len / 2}`;
      const txt = (x, s) => `<text x="${Math.round(x)}" y="${y + 62}" font-family="'Radio Canada', 'Helvetica Neue', Arial, sans-serif" font-size="36" text-anchor="middle" fill="${ink}">${s}</text>`;
      const g = new DOMParser().parseFromString(`<svg xmlns="${NS}"><g id="scale">`
        + `<rect x="${Math.round(sx)}" y="${y}" width="${Math.round(L / 2)}" height="14" fill="${ink}"/>`
        + `<rect x="${Math.round(sx + L / 2)}" y="${y}" width="${Math.round(L / 2)}" height="14" fill="none" stroke="${ink}" stroke-width="3"/>`
        + txt(sx, "0") + txt(sx + L / 2, half) + txt(sx + L, lab) + "</g></svg>", "image/svg+xml").documentElement.firstChild;
      sc.replaceWith(doc.importNode(g, true));
    }
    const ti = doc.querySelector("title");
    if (ti) ti.textContent = `${street.n} in ZIP 15068, with every road around it`;
    return new XMLSerializer().serializeToString(doc);
  }

  S.pages.poster = () => {
    const png = $("#poster-png"), msg = $("#poster-msg");
    const posterSrc = () => (S.isDark() ? "15068-roads-dark.svg" : "15068-roads.svg");
    if (png) {
      png.hidden = false;
      png.addEventListener("click", async () => {
        png.disabled = true;
        try { await savePNG(await getText(posterSrc()), S.isDark() ? "15068-roads-dark.png" : "15068-roads.png", msg); }
        catch (e) { if (msg) msg.textContent = "The poster didn't load just now. Try again, or download the SVG."; }
        png.disabled = false;
      });
    }
    const form = $("#street-form"), input = $("#street-q"), smsg = $("#street-msg"), out = $("#street-out");
    if (!form || !input) return;
    form.hidden = false;
    let listed = false, current = null;
    const fill = () => {
      if (listed) return;
      listed = true;
      loadWorld().then((W) => {
        const names = [...new Set(W.streets.map((s) => s.n))].sort((a, b) => a.localeCompare(b));
        $("#street-list").innerHTML = names.map((n) => `<option value="${esc(n)}">`).join("");
      }).catch(() => { listed = false; });
    };
    input.addEventListener("focus", fill, { once: true });
    /* a failed lookup must not leave the previous street's poster and downloads on screen */
    const clearOut = () => {
      out.hidden = true;
      current = null;
      const alt = $("#street-alt");
      if (alt) { alt.innerHTML = ""; alt.hidden = true; }
    };
    async function make(pick) {
      const q = input.value;
      if (!q.trim()) { smsg.textContent = "Type a street name first, like Leishman Avenue."; input.focus(); return; }
      smsg.textContent = "Making your poster…";
      try {
        const W = await loadWorld();
        const found = findStreets(q, W.streets);
        const street = pick ? found.find((x) => x.n === pick) || found[0] : found[0];
        if (!street) { clearOut(); smsg.textContent = `We couldn't find “${q.trim()}” in 15068. Try the full name, like Leishman Avenue.`; return; }
        const svg = streetPoster(await getText(posterSrc()), street, W);
        if (!svg) { clearOut(); smsg.textContent = `${street.n} has no mapped lines to draw.`; return; }
        current = { svg, file: S.slug(street.n) + "-15068" };
        const fig = $("#street-fig");
        const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" }));
        fig.innerHTML = `<img src="${url}" width="900" height="1200" alt="Poster of ${esc(street.n)} and the roads around it in ZIP 15068">`;
        const a = $("#street-svg");
        if (a.dataset.url) URL.revokeObjectURL(a.dataset.url);
        a.href = a.dataset.url = url;
        a.download = current.file + ".svg";
        out.hidden = false;
        const where = (street.t || []).map((t) => TOWN_NAME[t] || t).join(" and ");
        smsg.textContent = `Here's ${street.n}${where ? " in " + where : ""}.`;
        const others = found.filter((x) => x !== street).slice(0, 3);
        const alt = $("#street-alt");
        if (alt) {
          alt.innerHTML = others.length ? "Or: " + others.map((x) => `<button type="button" class="linkbtn" data-street="${esc(x.n)}">${esc(x.n)}${x.t && x.t.length ? " (" + esc(x.t.map((t) => TOWN_NAME[t] || t).join(", ")) + ")" : ""}</button>`).join(" · ") : "";
          alt.hidden = !others.length;
        }
        out.scrollIntoView({ block: "nearest" });
      } catch (err) {
        smsg.textContent = "The map data didn't load just now. Try again in a moment.";
      }
    }
    form.addEventListener("submit", (e) => { e.preventDefault(); make(); });
    const altBox = $("#street-alt");
    if (altBox) altBox.addEventListener("click", (e) => {
      const b = e.target.closest("[data-street]");
      if (b) { input.value = b.dataset.street; make(b.dataset.street); }
    });
    const spng = $("#street-png");
    if (spng) spng.addEventListener("click", async () => {
      if (!current) return;
      spng.disabled = true;
      await savePNG(current.svg, current.file + ".png", smsg);
      spng.disabled = false;
    });
  };

  /* pages with nothing live but <details> targets */
  ["towns", "people", "eat", "whats-new", "about", "sources"].forEach((p) => {
    const prev = S.pages[p];
    S.pages[p] = () => { if (prev) prev(); openTarget(); };
  });
})();

/* ==== js/60-map.js ==== */
/* NK15068 — the map pages: /map/ (the 2D map: search panel, layers, cards, deep links, near-me), /map/3d/,
   /directory/ (places and streets A to Z) and /search/.
   The HTML holds every label; this file draws the map (nkmap.js), fills cards and results, and keeps the view in the URL
   with NKS.setQS (replaceState, so one Back always leaves the page). Coordinates from "Use my location" are never
   stored or sent: only the street label is kept, and only when "Remember on this phone" is ticked. */
(function () {
  "use strict";
  const S = window.NKS;
  if (!S) return;
  const { $, $$, esc, fmt } = S;
  const isPhone = () => matchMedia("(max-width: 719px)").matches;
  const DOWNTOWN = [-3350, -40];
  const TOWN_NAME = { Allegheny: "Allegheny Township" };
  const townName = (t) => TOWN_NAME[t] || t;
  const plural = (n, one, many) => (n === 1 ? one : many || one + "s");
  const HALF_MILE = 804.672;
  /* "300 ft" under 0.1 mi (rounded to 50), else "0.4 mi" */
  const dist = (m) => { const mi = m / 1609.344; return mi < 0.1 ? `${Math.max(50, Math.round(m * 3.28084 / 50) * 50)} ft` : `${mi.toFixed(1)} mi`; };
  const readJSON = (sel) => { try { return JSON.parse($(sel)?.textContent || "null"); } catch (e) { return null; } };
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const flash = (btn, text) => { const was = btn.textContent; btn.textContent = text; setTimeout(() => { btn.textContent = was; }, 1800); };

  /* ---------------- places: the directory's de-duplication, town labels, map links (same rules as pages_map.py) ---------------- */
  const normName = (s) => String(s || "").toLowerCase().replace(/\b(new kensington|lower burrell|arnold|the|pa)\b/g, "").replace(/[^a-z0-9]/g, "");
  function dedupeKey(p) {
    const d = String(p.ph || "").replace(/\D/g, "");
    return d ? `${d}|${normName(p.n)}` : `${normName(p.n)}|${Math.floor(p.x / 50)},${Math.floor(p.y / 50)}`;
  }
  function dedupe(places) {
    const best = new Map();
    for (const p of places) { const k = dedupeKey(p), b = best.get(k); if (!b || (p.q || 0) > (b.q || 0)) best.set(k, p); }
    const keep = new Set(best.values());
    return places.filter((p) => keep.has(p));
  }
  const FIX_CITY = { "new kensington": "New Kensington", "new kensingtn": "New Kensington", "new kinsington": "New Kensington",
    "lower burrell": "Lower Burrell", arnold: "Arnold" };
  function townLabel(p) {
    const parts = String(p.a || "").split(",").map((s) => s.trim());
    return (parts.length >= 2 && FIX_CITY[parts[1].toLowerCase().replace(/-/g, " ")]) || p.t || "";
  }
  const slug = (s) => String(s || "").normalize("NFKD").replace(/[^\x00-\x7f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  const placeParam = (p) => `${slug(p.n)}~${Math.round(p.x)},${Math.round(p.y)}`;
  const mapURL = (k, v) => `${S.url("map/")}?${k}=${encodeURIComponent(v).replace(/%2C/g, ",").replace(/%7E/g, "~").replace(/%20/g, "+")}`;
  const aToZ = (a, b) => { const x = a.n.toLowerCase(), y = b.n.toLowerCase(); return x < y ? -1 : x > y ? 1 : (b.q || 0) - (a.q || 0); };
  function social(u) {
    const h = S.pubName(u);
    return /facebook\.com$/.test(h) ? "Facebook page" : /instagram\.com$/.test(h) ? "Instagram" : h;
  }

  /* ---------------- street keys and incident locations (as the blotter matches them) ---------------- */
  const streetKey = (n) => (window.NKSafety && window.NKSafety.streetKey ? window.NKSafety.streetKey(n)
    : window.NKSearch ? window.NKSearch.streetKey(n) : window.NKPets ? window.NKPets.streetKey(n) : null);
  const typeOk = (a, b) => !a || !b || a === b;
  function incStreets(i) {
    if (i.p === "place") return [];
    let l = String(i.l || "");
    if (i.p === "block") l = l.replace(/^\d+\s+block\s+of\s+/i, "");
    return l.split("&").map((s) => s.trim()).filter(Boolean);
  }
  const incNames = (i, k) => incStreets(i).some((n) => { const x = streetKey(n); return x && x.core === k.core && typeOk(k.type, x.type); });

  /* ======================================================================== /map/ */
  S.pages.map = () => mapPage().catch((e) => { console.warn(e); });

  async function mapPage() {
    const NK = window.NK, ex = $("#explorer"), canvas = $("#map-canvas"), loading = $("#map-loading"), card = $("#card");
    if (!NK || !ex || !canvas || !card) return;
    const cap = loading && loading.querySelector("figcaption");
    const Q = S.qs();
    let meta, W, places, streets;
    try {
      [meta, W, places, streets] = await Promise.all([NK.getJSON("meta.json"), NK.loadWorld({ keepLines: true }),
        NK.getJSON("places.json"), NK.getJSON("streets.json")]);
    } catch (e) {
      console.warn(e);
      if (cap) cap.textContent = "The map data didn't load just now. Check your connection and reload the page.";
      return;
    }
    places.forEach((p, i) => { p.id = i; });
    const police = (readJSON("#map-data") || {}).police || {};
    const map = new NK.Map2D(canvas, W, {
      initial: [-5200, -1700, -1400, 1700], scaleEl: $("#scale"), hold: true,
      onSelect: (p) => pick(p),
      onView: (v) => S.setQS({ at: `${Math.round(v.x)},${Math.round(v.y)},${+v.s.toFixed(3)}` }),
    });
    map.hold = true;
    map.setData(places, streets);
    NK.getTerrain(meta).then((T) => { map.terrain = T; map.dirty = true; }).catch((e) => console.warn(e));
    NK.loadBuildings(W).then((b) => { map.bld = b; map.dirty = true; }).catch((e) => console.warn(e));
    const L = map.layers;
    let settled = false, arriving = true, atSet = false;
    window.NKdebug = {
      get labels() { return settled ? map.drawnLabels.slice() : []; },
      get highlight() { return map.hl ? map.hl.name : null; },
      petDots: (id) => map.petDrawn.get(id) || 0,
      pin(id) {
        const p = map.pets.find((x) => x.id === id), pin = p && map.petPin(p);
        if (!pin) return null;
        const r = canvas.getBoundingClientRect();
        return { x: r.left + pin.x, y: r.top + pin.y };
      },
      view: () => map.view(),
    };

    /* ---------- where things go: on phone a selected point sits at 35% of the height, above the sheet ---------- */
    /* on a wide screen the card covers the left column, so things are centred in what's left */
    const offY = () => (isPhone() ? 0.15 * map.h : 0);
    const offX = () => (!isPhone() && map.w >= 900 ? 200 : 0);
    function go(x, y, s) {
      if (arriving && atSet) return;
      if (arriving) map.setView(x - offX() / s, y + offY() / s, s);
      else map.flyTo(x, y, s, { offsetX: offX(), offsetY: offY() });
    }
    const inset = () => (isPhone() ? { top: 64, bottom: 160 } : { top: 40, bottom: 30, left: map.w >= 900 ? 410 : 0, right: 70 });
    function fitBox(b) { if (!(arriving && atSet)) map.fitView(b, inset(), 3); }
    function fitPoints(pts, pad = 250) {
      if (!pts.length) return;
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      pts.forEach((p) => { x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x); y0 = Math.min(y0, p.y); y1 = Math.max(y1, p.y); });
      fitBox([x0 - pad, y0 - pad, x1 + pad, y1 + pad]);
    }

    /* ---------- the selection lives in the URL: one of place, street, near, pet, inc ---------- */
    const SEL = ["place", "street", "near", "pet", "inc"];
    function setSel(k, v) {
      const o = {};
      SEL.forEach((x) => { o[x] = null; });
      if (k) { o[k] = v; o.at = null; } // the selection sets the view; a later pan writes ?at= again
      S.setQS(o);
    }
    function clearMarks() { map.focus = null; map.here = null; map.highlightStreet(null); }

    /* ---------- lazy data: crime incidents and crashes ---------- */
    let safety = null, safetyP = null;
    function loadSafety() {
      if (!safetyP) {
        safetyP = NK.getJSON("safety.json").then((s) => {
          const inc = s.incidents || [];
          const ids = window.NKSafety ? window.NKSafety.incIds(inc) : inc.map((i, k) => String(k));
          inc.forEach((i, k) => { i.id = ids[k]; });
          map.setIncidents(inc);
          map.setCrashes((s.crashes && s.crashes.points) || []);
          safety = s;
          return s;
        });
        safetyP.catch(() => { safetyP = null; });
      }
      return safetyP;
    }

    /* ---------- the pets board ---------- */
    const P = window.NKPets;
    let petsDefault = !Q.has("layer");
    const boardP = P ? P.init({ W, streets, ui: { onChange: onPets } }).catch((e) => console.warn(e)) : Promise.resolve();
    function onPets(posts) {
      map.setPets(posts);
      if (petsDefault && P.board.known && posts.length) { petsDefault = false; setLayer("pets", true); }
    }

    /* ---------- layers ---------- */
    const lb = $("#layers-btn"), pop = $("#layers-pop");
    const setPop = (open) => { if (!pop || !lb) return; pop.hidden = !open; lb.setAttribute("aria-expanded", String(open)); };
    if (lb) lb.addEventListener("click", (e) => { e.stopPropagation(); setPop(pop.hidden); });
    document.addEventListener("click", (e) => { if (pop && !pop.hidden && !pop.contains(e.target) && !lb.contains(e.target)) setPop(false); });
    const LAYER_BTN = { pets: "#tpet", incidents: "#tinc", crashes: "#tcr", buildings: "#tbld", relief: "#trel" };
    const OVERLAYS = ["pets", "incidents", "crashes"];
    function syncLegend() {
      const on = { pet: L.pets, inc: L.incidents, cr: L.crashes };
      const lg = $("#inc-legend");
      if (!lg) return;
      lg.hidden = !(on.pet || on.inc || on.cr);
      $$("[data-l]", lg).forEach((el) => { el.hidden = !on[el.dataset.l]; });
    }
    async function setLayer(key, on, { write = false } = {}) {
      if ((key === "incidents" || key === "crashes") && on) {
        try { await loadSafety(); } catch (e) { console.warn(e); showMsg("The crime and crash data didn't load just now. Try again in a minute."); return; }
      }
      L[key] = on;
      const b = $(LAYER_BTN[key]);
      if (b) b.setAttribute("aria-pressed", String(on));
      map.hover = null; map.dirty = true;
      syncLegend();
      if (!on && map.sel && ((key === "pets" && map.sel.status) || (key === "crashes" && map.sel.yr != null) || (key === "incidents" && map.sel.k && map.sel.d))) closeCard();
      if (write) S.setQS({ layer: OVERLAYS.filter((k) => L[k]).join(",") || "none" });
    }
    Object.entries(LAYER_BTN).forEach(([key, sel]) => {
      const b = $(sel);
      if (b) b.addEventListener("click", () => { if (key === "pets") petsDefault = false; setLayer(key, !L[key], { write: OVERLAYS.includes(key) }); });
    });
    const zoomBy = (f) => { map.touched = true; map.zoomAt(f, map.w / 2, map.h / 2); };
    $("#zin")?.addEventListener("click", () => zoomBy(1.6));
    $("#zout")?.addEventListener("click", () => zoomBy(1 / 1.6));
    $("#home")?.addEventListener("click", () => { setPop(false); map.touched = true; const b = meta.bounds; map.fitView([b[0] + 300, b[1] + 300, b[2] - 300, b[3] - 300]); });
    $("#dt")?.addEventListener("click", () => { setPop(false); map.touched = true; map.flyTo(DOWNTOWN[0], DOWNTOWN[1], 1.3); });

    /* ---------- incident filters from the blotter's "Show these on the map" link ---------- */
    const layerParam = Q.has("layer") ? Q.get("layer").split(",") : [];
    const withInc = layerParam.includes("incidents");
    const F = { t: withInc ? Q.get("town") || "" : "", y: withInc ? Q.get("year") || "" : "", st: withInc ? (Q.get("street") || "").slice(0, 60) : "", c: withInc ? Q.get("c") || "" : "" };
    function incFilter() {
      const k = F.st ? streetKey(F.st) : null;
      return (i) => (!F.c || i.c === F.c) && (!F.t || i.t === F.t) && (!F.y || String(i.d).slice(0, 4) === F.y) && (!F.st || (k && incNames(i, k)));
    }
    const filtered = () => !!(F.c || F.t || F.y || F.st);
    function showFilterNote() {
      const lg = $("#inc-legend");
      if (!lg || !filtered()) return;
      const CAT = (window.NKSafety && window.NKSafety.CAT) || {};
      const what = [F.c && CAT[F.c], F.t, F.y, F.st].filter(Boolean).join(" · ");
      lg.insertAdjacentHTML("beforeend", `<p class="lg-filter" data-l="inc">Showing ${esc(what)} <button type="button" class="linkbtn" id="inc-all">Show all</button></p>`);
      $("#inc-all").addEventListener("click", () => {
        F.c = F.t = F.y = F.st = "";
        map.incVisible = () => true; map.dirty = true;
        $(".lg-filter", lg)?.remove();
        S.setQS({ town: null, year: null, street: null, c: null });
      });
    }

    /* ---------- category chips; on phone they open from the Filter button ---------- */
    const chips = $("#chips"), fb = $("#filter-btn");
    if (chips) {
      const counts = {};
      places.forEach((p) => { counts[p.g] = (counts[p.g] || 0) + 1; });
      chips.innerHTML = `<button class="chip" type="button" data-g="*" aria-pressed="true">All ${fmt(places.length)}</button>` +
        Object.entries(meta.groups).filter(([k]) => counts[k]).map(([k, v]) =>
          `<button class="chip" type="button" data-g="${k}" aria-pressed="false"><i style="background:${NK.GROUP_COLORS[k]}"></i>${esc(v)}</button>`).join("");
      const setCat = (g, write) => {
        if (g !== "*" && !meta.groups[g]) g = "*";
        $$(".chip", chips).forEach((x) => x.setAttribute("aria-pressed", String(x.dataset.g === g)));
        map.filter = new Set(g === "*" ? Object.keys(NK.GROUP_COLORS) : [g]);
        map.dirty = true;
        if (write) S.setQS({ cat: g === "*" ? null : g });
      };
      chips.addEventListener("click", (e) => { const b = e.target.closest(".chip"); if (b) setCat(b.dataset.g, true); });
      if (Q.get("cat")) setCat(Q.get("cat"), false);
      if (fb) fb.addEventListener("click", () => {
        const open = !chips.hasAttribute("data-open");
        chips.toggleAttribute("data-open", open);
        fb.setAttribute("aria-expanded", String(open));
      });
    }

    /* ---------- the card: a panel on desktop, a bottom sheet with a 140 px peek on phone ---------- */
    let cardKind = null;
    /* phone: zoom and scale sit above the sheet; desktop: the card stops short of the search panel */
    const panel = $("#search-panel");
    function syncSheet() {
      const phone = isPhone();
      ex.style.setProperty("--sheet", !card.hidden && phone ? card.offsetHeight + "px" : "0px");
      if (phone || !panel) { card.style.maxHeight = ""; return; }
      const r = $("#results"), ph = panel.offsetHeight - (r && !r.hidden ? r.offsetHeight : 0);
      card.style.maxHeight = Math.max(160, ex.clientHeight - panel.offsetTop - ph - 26) + "px";
    }
    if (window.ResizeObserver && chips) new ResizeObserver(syncSheet).observe(chips);
    if (window.ResizeObserver) new ResizeObserver(syncSheet).observe(card);
    addEventListener("resize", syncSheet);
    function setSheet(state) {
      card.dataset.sheet = state;
      const g = $(".sheet-grip", card);
      if (g) { g.setAttribute("aria-expanded", String(state === "full")); g.setAttribute("aria-label", state === "full" ? "Show less" : "Show more"); }
      syncSheet();
    }
    function showCard(html, { top = "var(--ink)", kind = "msg" } = {}) {
      cardKind = kind;
      card.dataset.kind = kind;
      card.style.setProperty("--card-top", top);
      card.innerHTML = `<button class="sheet-grip" type="button" aria-expanded="false" aria-label="Show more"><span></span></button>`
        + `<button class="close" type="button" aria-label="Close">×</button><div class="card-in">${html}</div>`;
      card.hidden = false;
      card.scrollTop = 0;
      setSheet("peek");
      S.relabel(card);
    }
    const showMsg = (text, extra = "") => showCard(`<p class="msg">${esc(text)}</p>${extra}`);
    function closeCard() {
      card.hidden = true; cardKind = null;
      map.sel = null; clearMarks(); map.dirty = true;
      setSel(null);
      syncSheet();
    }
    card.addEventListener("click", async (e) => {
      if (e.target.closest(".close")) { closeCard(); return; }
      if (e.target.closest(".sheet-grip")) { setSheet(card.dataset.sheet === "full" ? "peek" : "full"); return; }
      const cp = e.target.closest("[data-copy]");
      if (cp) { const ok = await S.copy(location.href); flash(cp, ok ? "Link copied" : "Couldn't copy"); return; }
      const inc = e.target.closest("[data-inc]");
      if (inc) { const i = safety && safety.incidents.find((x) => x.id === inc.dataset.inc); if (i) focusIncident(i); return; }
      const pl = e.target.closest("[data-place]");
      if (pl) { const p = places[+pl.dataset.place]; if (p) focusPlace(p); }
    });
    /* keyboard focus inside a peeking sheet opens it, so nothing focused is out of sight */
    card.addEventListener("focusin", (e) => {
      if (isPhone() && card.dataset.sheet === "peek" && !e.target.closest(".sheet-grip, .close")) setSheet("full");
    });
    card.addEventListener("change", (e) => {
      const r = e.target.closest("[data-remember]");
      if (!r) return;
      if (r.checked) S.local.set("nk-corner", r.dataset.remember); else S.local.del("nk-corner");
    });
    /* drag the grip: up opens the sheet, down closes it a step at a time */
    let drag = null;
    card.addEventListener("pointerdown", (e) => { if (e.target.closest(".sheet-grip") && isPhone()) drag = { y: e.clientY }; });
    addEventListener("pointerup", (e) => {
      if (!drag) return;
      const dy = e.clientY - drag.y;
      drag = null;
      if (dy < -30) setSheet("full");
      else if (dy > 40) { if (card.dataset.sheet === "full") setSheet("peek"); else closeCard(); }
    });
    const copyBtn = () => `<button type="button" class="cbtn" data-copy>Copy link</button>`;

    /* ---------- cards ---------- */
    function placeCard(p) {
      const col = NK.GROUP_COLORS[p.g] || "var(--ink)";
      const acts = [];
      if (p.ph && S.tels(p.ph).length) acts.push(S.telLink(p.ph, "Call {n}"));
      acts.push(`<a class="cbtn" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.n + " " + p.lat + "," + p.lon)}" target="_blank" rel="noopener">Directions</a>`);
      if (p.w) acts.push(`<a class="cbtn" href="${esc(p.w)}" target="_blank" rel="noopener">Website</a>`);
      acts.push(copyBtn());
      const more = [townLabel(p), p.s ? `<a href="${esc(p.s)}" target="_blank" rel="noopener">${esc(social(p.s))}</a>` : ""].filter(Boolean);
      showCard(`<p class="kicker"><span class="sw" style="background:${col}"></span>${esc(S.cap(p.c || ""))}${meta.groups[p.g] ? " · " + esc(meta.groups[p.g]) : ""}</p>
        <h3>${esc(p.n)}</h3>${p.a ? `<p class="c-addr">${esc(p.a)}</p>` : ""}
        <p class="c-acts">${acts.join("")}</p>${more.length ? `<p class="meta">${more.join(" · ")}</p>` : ""}`, { top: col, kind: "place" });
    }
    const PREC = { intersection: "Pinned at the cross streets given.", picked: "Pinned where the poster marked it.", street: "" };
    function petCard(p) {
      const st = P.STATUS[p.status] || "Lost", aw = P.animalWord(p), top = `var(--pet-${p.status})`;
      const street = p.prec === "street" || typeof p.x !== "number";
      const where = street
        ? (p.placeLabel || p.near ? `Somewhere on ${p.placeLabel || p.near}${p.town ? ", " + p.town : ""}. No cross street was given.` : "")
        : P.nearLine(p);
      const d = p.date || String(p.created || "").slice(0, 10);
      const acts = [`<a class="cbtn" href="${esc(S.url("lost-pets/flyer/"))}?pet=${esc(p.id)}">Flyer</a>`];
      if (p.url) acts.push(`<a class="cbtn" href="${esc(p.url)}" target="_blank" rel="noopener">See this post ›</a>`);
      acts.push(`<a class="cbtn" href="${esc(S.url("lost-pets/"))}#${esc(p.id)}">On the board</a>`, copyBtn());
      showCard(`<p class="kicker"><span class="sw" style="background:${top}"></span>${esc(st)} · ${esc(aw)}</p>
        <h3>${p.name ? `“${esc(p.name)}”` : esc(`${st} ${aw}`)}</h3>
        ${where ? `<p class="c-where">${esc(where)}</p>` : ""}<p class="c-acts">${acts.join("")}</p>
        ${p.desc ? `<p class="txt">${esc(p.desc)}</p>` : ""}
        ${d ? `<p class="c-line">${esc(st)} ${esc(S.apDay(d))} <span data-ago="${esc(d)}" data-paren></span></p>` : ""}
        ${p.contact ? `<p class="c-line">${P.contactHTML(p)}</p>` : ""}
        ${!street && PREC[p.prec] ? `<p class="meta">${PREC[p.prec]}</p>` : ""}`, { top, kind: "pet" });
    }
    function incidentCard(p) {
      const Sf = window.NKSafety || { TYPE: {}, CAT: {}, PREC: {} }, top = `var(--inc-${esc(p.c)})`;
      const blot = `${S.url("crime/blotter/")}#inc-${encodeURIComponent(p.id || "")}`;
      showCard(`<p class="kicker"><span class="sw" style="background:${top}"></span>${esc(Sf.CAT[p.c] || "")}${p.pi ? " · police involved" : ""}</p>
        <h3>${esc(Sf.TYPE[p.k] || S.cap(p.k))}</h3>
        <p class="c-where">${esc(S.apDate(p.d))} · ${esc(p.l)}, ${esc(p.t)}</p>
        <p class="c-acts"><a class="cbtn" href="${esc(blot)}">On the police blotter</a>${copyBtn()}</p>
        <p class="txt">${esc(p.s)}</p><p class="credit">${S.credit(p.src)}</p>
        <p class="meta">Location precision: ${esc(Sf.PREC[p.p] || p.p)}. Reported in the news; not a complete record.</p>`, { top, kind: "inc" });
    }
    function crashCard(p) {
      const when = S.apDate(p.mo ? `${p.yr}-${String(p.mo).padStart(2, "0")}` : String(p.yr));
      const hurt = [p.f ? `${p.f} killed` : "", p.s ? `${p.s} seriously injured` : ""].filter(Boolean).join(" · ");
      showCard(`<p class="kicker"><span class="tri-key${p.f ? "" : " hollow"}"></span>${esc(p.col || "Crash")}</p>
        <h3>${p.f ? "Fatal crash" : "Serious-injury crash"}</h3>
        <p class="c-where">${esc(when)} · ${esc(p.t)}</p>${hurt ? `<p class="c-line">${esc(hurt)}</p>` : ""}
        <p class="c-acts"><a class="cbtn" href="${esc(S.url("crashes/"))}">Serious crashes</a></p>
        <p class="credit">${S.credit(safety && safety.crashes && safety.crashes.source)}</p>
        <p class="meta">Location as recorded by the investigating police agency.</p>`, { kind: "crash" });
    }

    /* ---------- "Near this street" and "Near this corner" (spec section 5), measured on this device ---------- */
    const polTel = (t) => { const r = police[t]; return r ? `${esc(t)} ${S.telLink(r.ph, "{n}", "tel-inline")}` : ""; };
    function policeLine(towns) {
      const core = towns.filter((t) => police[t]);
      if (!core.length) return "";
      return `<p class="near-l"><b>Police</b> ${core.length === 1 ? `${polTel(core[0])} (non-emergency)` : `${core.map(polTel).join(" or ")}, depending on the block`}</p>`;
    }
    const nearestTo = (dFn, test) => {
      let best = null, bd = Infinity;
      for (const p of places) { if (!test(p)) continue; const d = dFn(p); if (d < bd) { bd = d; best = p; } }
      return best ? { p: best, d: bd } : null;
    };
    function nearbyHTML(dFn) {
      /* the spec's tests (grocer|supermarket, pharmac|drug, the play group), narrowed to real parks and away from drug treatment */
      const kinds = [["Grocery", (p) => /grocer|supermarket/i.test(p.c || "")],
        ["Pharmacy", (p) => /pharmac|drug/i.test(p.c || "") && !/treatment/i.test(p.c || "")],
        ["Park", (p) => p.g === "play" && /park|field|playground/i.test(p.c || "")]];
      const rows = kinds.map(([label, test]) => {
        const hit = nearestTo(dFn, test);
        if (!hit) return "";
        const call = hit.p.ph && S.tels(hit.p.ph).length ? S.telLink(hit.p.ph, "Call") : "";
        return `<li><span class="nb-k">${label}</span><span class="nb-p"><button type="button" class="linkbtn" data-place="${hit.p.id}">${esc(hit.p.n)}</button>, ${dist(hit.d)}</span>${call}</li>`;
      }).join("");
      return rows ? `<p class="near-h">Nearest grocery, pharmacy and park</p><ul class="near-list">${rows}</ul>` : "";
    }
    const incRow = (i) => `<li><button type="button" class="linkbtn" data-inc="${esc(i.id)}">${esc(S.apDate(i.d))} · ${esc(((window.NKSafety || {}).TYPE || {})[i.k] || S.cap(i.k))} · ${esc(i.l)}</button></li>`;
    const split = (list) => {
      const c = {};
      list.forEach((i) => { c[i.t] = (c[i.t] || 0) + 1; });
      return Object.entries(c).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([t, n]) => `${n} in ${t}`).join(", ");
    };
    const newest = (list) => [...list].sort((a, b) => String(b.d).localeCompare(String(a.d)));
    const firstYear = (list) => Math.min(...list.map((i) => +String(i.d).slice(0, 4)));
    function crashYears() {
      const ys = ((safety && safety.crashes && safety.crashes.stats) || []).map((r) => r.year);
      return ys.length ? [Math.min(...ys), Math.max(...ys)] : null;
    }
    function crashLine(list) {
      if (!safety) return "";
      if (!list.length) { const y = crashYears(); return `<p class="near-l">Serious crashes within 100 ft: none${y ? ` from ${y[0]} through ${y[1]}` : ""}.</p>`; }
      const ys = [...new Set(list.map((c) => c.yr))].sort();
      return `<p class="near-l">Serious crashes within 100 ft: ${list.length} (${ys.join(", ")}).</p>`;
    }
    function petsLine(dFn) {
      if (!P || !P.board.known) return "";
      const n = P.board.posts.filter((p) => typeof p.x === "number" && dFn(p) <= HALF_MILE).length;
      return `<p class="near-l">Open lost and found posts within ½ mile: ${n}.</p>`;
    }
    const rememberBox = (label) => `<label class="remember"><input type="checkbox" data-remember="${esc(label)}"${S.local.get("nk-corner") === label ? " checked" : ""}> Remember on this phone</label>`;

    async function streetCard(s) {
      const lines = W.lines.filter((l) => l.n === s.n);
      const dFn = (p) => Math.min(...lines.map((l) => NK.lineDist(p.x, p.y, l.pts)));
      try { await loadSafety(); } catch (e) { console.warn(e); }
      const mi = s.m / 1609.344;
      const towns = (s.t || []).map(townName);
      const head = [`${fmt(s.m)} m (${mi < 1 ? mi.toFixed(2) : mi.toFixed(1)} mi) in 15068`, s.a ? `${fmt(s.a)} addresses` : "",
        towns.length ? `Runs through ${towns.join(", ")}` : ""].filter(Boolean).join(" · ");
      let incHTML = "";
      if (safety) {
        const k = streetKey(s.n);
        const all = safety.incidents || [];
        const on = [], near = [];
        all.forEach((i) => {
          const d = dFn(i);
          if ((k && incNames(i, k) && (s.t || []).includes(i.t)) || d <= 30) on.push(i);
          else if (d <= 120) near.push(i);
        });
        if (on.length) {
          const u = `${S.url("crime/blotter/")}?street=${encodeURIComponent(s.n).replace(/%20/g, "+")}`;
          incHTML = `<p class="near-l"><b>${on.length} news-reported ${plural(on.length, "incident")} on ${esc(s.n)}</b> since ${firstYear(on)} (${esc(split(on))}).</p>
            <ul class="near-list">${newest(on).slice(0, 3).map(incRow).join("")}</ul><p><a class="go" href="${esc(u)}">See all on the police blotter ›</a></p>`;
        } else {
          incHTML = `<p class="near-l">No news-reported incidents on ${esc(s.n)}${all.length ? ` since ${firstYear(all)}` : ""}.</p>`;
        }
        if (near.length) incHTML += `<p class="near-l">${near.length} more within a block (400 ft).</p>`;
        incHTML += crashLine(((safety.crashes && safety.crashes.points) || []).filter((c) => dFn(c) <= 30));
      }
      showCard(`<p class="kicker"><span class="sw" style="background:var(--map-focus)"></span>Street</p>
        <h3>${S.streetHead(s.n)}${S.routes(s.ref)}</h3><p class="c-where">${esc(head)}</p>
        <p class="c-acts">${copyBtn()}</p>
        <div class="near">${incHTML}${petsLine(dFn)}${nearbyHTML(dFn)}${policeLine(s.t || [])}</div>`, { top: "var(--map-focus)", kind: "street" });
    }
    function townOf(x, y) {
      const ctx = map.ctx;
      ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
      const t = (W.towns || []).filter((t) => t.core).find((t) => ctx.isPointInPath(t.p, x, y)) || (W.towns || []).find((t) => ctx.isPointInPath(t.p, x, y));
      ctx.restore();
      return t ? t.n : null;
    }
    async function cornerCard(spot) {
      const dFn = (p) => Math.hypot(p.x - spot.x, p.y - spot.y);
      try { await loadSafety(); } catch (e) { console.warn(e); }
      const town = townOf(spot.x, spot.y);
      let incHTML = "";
      if (safety) {
        const on = (safety.incidents || []).filter((i) => dFn(i) <= 120);
        incHTML = on.length
          ? `<p class="near-l"><b>${on.length} news-reported ${plural(on.length, "incident")} within a block (400 ft)</b> since ${firstYear(on)} (${esc(split(on))}).</p><ul class="near-list">${newest(on).slice(0, 3).map(incRow).join("")}</ul>`
          : `<p class="near-l">No news-reported incidents within a block (400 ft).</p>`;
        incHTML += crashLine(((safety.crashes && safety.crashes.points) || []).filter((c) => dFn(c) <= 30));
      }
      const label = spot.label ? `Near ${P ? P.shortStreet(spot.label) : spot.label}` : "This spot";
      showCard(`<p class="kicker"><span class="sw" style="background:var(--here)"></span>${spot.located ? "Your location" : "Corner"}</p>
        <h3>${esc(label)}</h3>${town ? `<p class="c-where">In ${esc(townName(town))}</p>` : ""}
        <p class="c-acts">${copyBtn()}</p>
        <div class="near">${incHTML}${petsLine(dFn)}${nearbyHTML(dFn)}${policeLine(town ? [town] : [])}</div>
        ${rememberBox(spot.text || label)}`, { top: "var(--here)", kind: "near" });
    }

    /* ---------- focusing things ---------- */
    function focusPlace(p, { write = true } = {}) {
      if (!p) return;
      clearMarks();
      if (!map.filter.has(p.g)) $("#chips .chip[data-g='*']")?.click();
      go(p.x, p.y, 2.6);
      map.sel = p; map.dirty = true;
      placeCard(p);
      if (write) setSel("place", placeParam(p));
    }
    async function focusStreet(s, { write = true } = {}) {
      if (!s) return;
      clearMarks();
      map.sel = null;
      map.highlightStreet(s.n);
      if (!(arriving && atSet)) map.fitStreet(s.n, inset());
      if (write) setSel("street", s.n);
      await streetCard(s);
    }
    async function focusCorner(spot, { write = true, zoom = 1.6 } = {}) {
      clearMarks();
      map.sel = null;
      map.here = { x: spot.x, y: spot.y }; map.focus = { x: spot.x, y: spot.y };
      go(spot.x, spot.y, zoom);
      if (write) setSel("near", spot.text || spot.label);
      await cornerCard(spot);
    }
    function focusPet(p, { write = true } = {}) {
      clearMarks();
      if (!L.pets) setLayer("pets", true);
      petsDefault = false;
      if ((p.prec === "street" || typeof p.x !== "number") && (p.placeLabel || p.near)) {
        map.sel = null;
        map.highlightStreet(p.placeLabel || p.near, p.town || null);
        if (!(arriving && atSet)) { if (!map.fitStreet(null, inset()) && typeof p.x === "number") go(p.x, p.y, 0.6); }
      } else if (typeof p.x === "number") {
        map.focus = { x: p.x, y: p.y };
        go(p.x, p.y, 1.25);
        map.sel = p;
      }
      map.dirty = true;
      petCard(p);
      if (write) setSel("pet", p.id);
    }
    async function focusIncident(i, { write = true } = {}) {
      clearMarks();
      await setLayer("incidents", true);
      if (!map.incVisible(i)) { map.incVisible = () => true; $(".lg-filter")?.remove(); }
      map.focus = { x: i.x, y: i.y };
      go(i.x, i.y, 1.25);
      map.sel = i; map.dirty = true;
      incidentCard(i);
      if (write) setSel("inc", i.id);
    }
    /* a tap on the map */
    function pick(p) {
      if (!p) { if (cardKind && cardKind !== "street" && cardKind !== "near") closeCard(); return; }
      clearMarks();
      if (p.status) { focusPetTap(p); return; }
      if (p.yr != null) { crashCard(p); setSel(null); return; }
      if (p.k && p.d) { incidentCard(p); setSel("inc", p.id); return; }
      placeCard(p); setSel("place", placeParam(p));
    }
    function focusPetTap(p) { map.sel = p; petCard(p); setSel("pet", p.id); }

    /* ---------- deep links ---------- */
    function findPlace(v) {
      const m = String(v).match(/^(.*?)(?:~(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?))?$/);
      const sl = slug(m[1]), hasXY = m[2] != null, x = +m[2], y = +m[3];
      const same = places.filter((p) => slug(p.n) === sl);
      const nearest = (list) => {
        let best = null, bd = Infinity;
        list.forEach((p) => { const d = Math.hypot(p.x - x, p.y - y); if (d < bd) { bd = d; best = p; } });
        return { p: best, d: bd };
      };
      if (hasXY) {
        let n = nearest(same);
        if (n.p && n.d <= 200) return { p: n.p };
        n = nearest(places);
        if (n.p && n.d <= 30) return { p: n.p };
        return { x, y };
      }
      return same.length ? { p: [...same].sort((a, b) => (b.q || 0) - (a.q || 0))[0] } : {};
    }
    function findStreet(name) {
      const n = String(name || "").trim().toLowerCase();
      if (!n) return null;
      const exact = streets.find((s) => s.n.toLowerCase() === n);
      if (exact) return exact;
      const k = streetKey(name);
      const keyed = k ? streets.filter((s) => { const x = streetKey(s.n); return x && x.core === k.core && typeOk(k.type, x.type); }) : [];
      return keyed.sort((a, b) => (b.a || 0) - (a.a || 0) || b.m - a.m)[0] || streets.find((s) => s.n.toLowerCase().startsWith(n)) || null;
    }
    async function geocode(text) {
      if (!P) return null;
      await boardP;
      return P.geocodeNear(P.cleanNear(text), S.town() || "New Kensington");
    }
    async function arrive() {
      if (Q.has("at")) {
        const [x, y, s] = Q.get("at").split(",").map(Number);
        if ([x, y, s].every(Number.isFinite) && s > 0) { map.setView(x, y, s); atSet = true; }
      }
      const want = layerParam.filter((k) => OVERLAYS.includes(k));
      for (const k of want) await setLayer(k, true);
      if (want.includes("incidents")) {
        map.incVisible = incFilter();
        showFilterNote();
        const vis = (safety ? safety.incidents : []).filter(map.incVisible);
        if (filtered() && !vis.length) showMsg("No incidents match those filters.");
        else if (!Q.has("inc")) fitPoints(vis.length ? vis : safety ? safety.incidents : []);
      } else if (want.includes("crashes")) fitPoints((safety && safety.crashes.points) || []);
      if (Q.get("place")) {
        const f = findPlace(Q.get("place"));
        if (f.p) focusPlace(f.p, { write: false });
        else if (Number.isFinite(f.x)) { go(f.x, f.y, 2); showMsg("That place isn't in the current map data."); }
        else showMsg("That place isn't in the current map data.");
      } else if (Q.get("street")) {
        const s = findStreet(Q.get("street"));
        if (s) await focusStreet(s, { write: false });
        else if (!want.includes("incidents")) showMsg(`We couldn't find a street called “${Q.get("street")}” in 15068.`);
      } else if (Q.get("near")) {
        const g = await geocode(Q.get("near"));
        if (g) await focusCorner({ x: g.x, y: g.y, label: g.label, text: Q.get("near") }, { write: false });
        else showMsg("We couldn't find that corner. Try two street names, like 5th Avenue & 9th Street.");
      } else if (Q.get("pet")) {
        await boardP;
        const id = Q.get("pet"), p = P && P.board.posts.find((x) => x.id === id);
        if (p) focusPet(p, { write: false });
        else if (P && P.board.state === "unknown") showMsg("The lost and found board didn't load just now, so that listing can't be shown.", `<p><a class="go" href="${esc(S.url("lost-pets/"))}">Lost and found pets ›</a></p>`);
        else showMsg("That listing isn't open on the board now. Its owner may have closed it.", `<p><a class="go" href="${esc(S.url("lost-pets/"))}#board">See the board ›</a></p>`);
      } else if (Q.get("inc")) {
        try { await loadSafety(); } catch (e) { console.warn(e); }
        const i = safety && safety.incidents.find((x) => x.id === Q.get("inc"));
        if (i) await focusIncident(i, { write: false });
        else showMsg("That incident isn't in the current data.", `<p><a class="go" href="${esc(S.url("crime/blotter/"))}">The police blotter ›</a></p>`);
      }
    }
    const release = () => { map.hold = false; map.dirty = true; if (loading) loading.hidden = true; };
    const done = arrive().catch((e) => console.warn(e));
    await Promise.race([done, wait(4000)]);
    release();
    await done;
    arriving = false;
    map.drawnLabels = []; map.dirty = true;
    settled = true;

    /* ---------- the search panel (NKSearch) ---------- */
    const q = $("#q"), res = $("#results");
    if (!q || !res) return;
    let sdata = null, spot = null, rows = [], showAll = false;
    const saved = S.local.get("nk-corner");
    const loadSearch = () => (window.NKSearch ? window.NKSearch.load() : Promise.reject(new Error("search.js")));
    if (saved) geocode(saved).then((g) => { if (g) spot = { x: g.x, y: g.y, label: g.label }; }).catch(() => {});
    function hideResults() { res.innerHTML = ""; res.hidden = true; }
    function locRow() {
      return `<div class="res res-loc"><button type="button" class="res-go" data-k="loc"><i class="loc-i"></i><b>Use my location</b><small>Find what's near you</small></button></div>`
        + (saved ? `<div class="res"><button type="button" class="res-go" data-k="saved"><i class="loc-i"></i><b>Near ${esc(P ? P.shortStreet(saved) : saved)}</b><small>Your saved corner</small></button></div>` : "");
    }
    function rowHTML(r) {
      if (r.kind === "msg") return `<p class="none">${esc(r.text)}</p>`;
      if (r.kind === "call") {
        const ph = r.x.ph[0];
        return `<div class="res res-call"><a class="res-go" href="${esc(S.url(r.x.u))}"><i class="call-i"></i><b>${esc(r.x.n)}</b><small>${esc(r.x.t)} · phone number</small></a>${ph ? S.telLink(ph, "Call", "tel res-tel") : ""}</div>`;
      }
      const call = r.ph && S.tels(r.ph).length ? S.telLink(r.ph, "Call", "tel res-tel") : "";
      const icon = r.col ? `<i style="background:${r.col}"></i>` : `<i class="loc-i"></i>`;
      return `<div class="res"><button type="button" class="res-go" data-k="${esc(r.k)}">${icon}<b>${r.name}</b><small>${esc(r.sub)}</small></button>${call}</div>`;
    }
    function drawResults() {
      const t = q.value.trim();
      if (!t) { res.innerHTML = locRow(); res.hidden = false; return; }
      if (!sdata) { res.innerHTML = `<p class="none">Searching…</p>`; res.hidden = false; return; }
      const m = window.NKSearch.match(t, sdata, { town: S.town(), pets: P ? P.board.posts : [], spot });
      rows = [];
      const G = m.groups;
      if (G.corner.length && P) {
        const g = P.geocodeNear(P.cleanNear(t), S.town() || "New Kensington");
        rows.push(g ? { k: "c", name: esc(`Near ${P.shortStreet(g.label)}`), sub: "Corner · what's near it", col: "", g }
          : { kind: "msg", text: "We couldn't find that corner. Try two street names, like 5th Avenue & 9th Street." });
      }
      G.streets.slice(0, 8).forEach((s) => rows.push({ k: "s:" + s.n, name: esc(s.n) + S.routes(s.ref),
        sub: ["Street", fmt(s.m) + " m", (s.t || []).map(townName).join(", ")].filter(Boolean).join(" · "), col: "var(--map-focus)" }));
      G.places.forEach((p) => rows.push({ k: "p:" + p.id, name: esc(p.n), ph: p.ph, col: NK.GROUP_COLORS[p.g],
        sub: [S.cap(p.c || ""), S.shortAddr(p.a) || townLabel(p), spot && p._d != null ? dist(p._d) : ""].filter(Boolean).join(" · ") }));
      G.call.slice(0, 6).forEach((r) => rows.push({ kind: "call", x: r }));
      G.pets.forEach((p) => rows.push({ k: "pet:" + p.id, name: esc(P.headline(p)), col: `var(--pet-${p.status})`, sub: P.where(p) || "Lost and found board" }));
      if (!rows.length) { res.innerHTML = `<p class="none">Nothing found for “${esc(t)}”. Try a business, a street (“5th Ave”) or a corner (“5th & 9th”).</p>`; res.hidden = false; return; }
      const n = rows.length, lim = showAll ? n : 50;
      res.innerHTML = rows.slice(0, lim).map(rowHTML).join("") + (n > lim ? `<button type="button" class="res-all" data-k="all">Show all ${fmt(n)}</button>` : "");
      res.hidden = false;
    }
    function open(k) {
      if (k === "all") { showAll = true; drawResults(); return; }
      if (k === "loc") { askLocation(); return; }
      q.blur();
      if (k === "saved") { geocode(saved).then((g) => g && focusCorner({ x: g.x, y: g.y, label: g.label, text: saved })); hideResults(); return; }
      if (k === "c") { const r = rows.find((x) => x.k === "c"); if (r) focusCorner({ x: r.g.x, y: r.g.y, label: r.g.label, text: q.value.trim() }); }
      else if (k.startsWith("s:")) focusStreet(streets.find((s) => s.n === k.slice(2)));
      else if (k.startsWith("p:")) focusPlace(places[+k.slice(2)]);
      else if (k.startsWith("pet:")) { const p = P.board.posts.find((x) => x.id === k.slice(4)); if (p) focusPet(p); }
      hideResults();
      if (isPhone() && chips) { chips.removeAttribute("data-open"); fb?.setAttribute("aria-expanded", "false"); }
    }
    let timer = 0;
    q.addEventListener("focus", () => { if (!sdata) loadSearch().then((d) => { sdata = d; drawResults(); }).catch((e) => console.warn(e)); drawResults(); });
    q.addEventListener("input", () => { showAll = false; clearTimeout(timer); timer = setTimeout(drawResults, 120); });
    q.addEventListener("keydown", (e) => {
      if (e.key === "Escape") { hideResults(); q.blur(); }
      if (e.key !== "Enter") return;
      e.preventDefault();
      clearTimeout(timer); drawResults();
      const first = res.querySelector("[data-k]:not([data-k='loc']):not([data-k='saved']):not([data-k='all'])") || res.querySelector("a.res-go");
      if (first && first.dataset.k) open(first.dataset.k); else if (first) location.href = first.href;
    });
    res.addEventListener("click", (e) => { const b = e.target.closest("button[data-k]"); if (b) open(b.dataset.k); });
    document.addEventListener("click", (e) => { if (!res.hidden && !e.composedPath().includes(res) && e.target !== q) hideResults(); });
    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape") return;
      if (pop && !pop.hidden) { setPop(false); lb.focus(); }
    });

    /* ---------- Use my location: the consent sentence first; only the street label is ever kept ---------- */
    function askLocation() {
      if (!navigator.geolocation) { res.innerHTML = `<p class="none">This browser can't share a location. Type a corner instead.</p>`; return; }
      res.innerHTML = `<div class="consent"><p>Your location is used on this device to find your nearest street. It isn't sent anywhere.</p>
        <p><button type="button" class="btn-line inline" id="loc-go">Continue</button> <button type="button" class="btn-line inline" id="loc-no">Cancel</button></p></div>`;
      $("#loc-no").addEventListener("click", hideResults);
      $("#loc-go").addEventListener("click", () => {
        res.innerHTML = `<p class="none">Finding your nearest street…</p>`;
        navigator.geolocation.getCurrentPosition(async (pos) => {
          const x = (pos.coords.longitude - meta.origin[0]) * meta.kx, y = (meta.origin[1] - pos.coords.latitude) * meta.ky;
          const [x0, y0, x1, y1] = meta.bounds;
          if (x < x0 || x > x1 || y < y0 || y > y1) { res.innerHTML = `<p class="none">You look to be outside 15068. Type a corner instead.</p>`; return; }
          await boardP;
          const names = P ? P.nearestStreets(x, y, 150) : [];
          if (!names.length) { res.innerHTML = `<p class="none">We couldn't find a street near you. Type a corner instead.</p>`; return; }
          hideResults();
          const label = names.join(" & ");
          focusCorner({ x, y, label, text: "Near " + names.map(P.shortStreet).join(" & "), located: true }, { write: false });
        }, () => { res.innerHTML = `<p class="none">Your location isn't available. Type a corner instead.</p>`; },
        { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 });
      });
    }
  }

  /* ======================================================================== /map/3d/ */
  S.pages.map3d = () => map3dPage().catch((e) => { console.warn(e); });

  const VIEWS = {
    downtown: { x: -3350, y: -40, dist: 1500, pitch: 0.55, yaw: -0.6 },
    hills: { x: 900, y: -1500, dist: 4200, pitch: 0.3, yaw: 2.3 },
    zip: { x: -400, y: 0, dist: 16500, pitch: 0.95, yaw: -0.35 },
  };
  async function map3dPage() {
    const NK = window.NK, ex = $("#explorer"), host = $("#gl-host"), loading = $("#map-loading");
    if (!NK || !ex || !host) return;
    const cap = loading && loading.querySelector("figcaption");
    const fail = (t) => { if (cap) cap.textContent = t; if (loading) loading.hidden = false; };
    if (!window.THREE || !NK.Map3D) { fail("The 3D view needs the three.js library, which didn't load. Check your connection and reload, or use the flat map."); return; }
    let W, meta, T, bld;
    try {
      [meta, W] = await Promise.all([NK.getJSON("meta.json"), NK.loadWorld()]);
      [T, bld] = await Promise.all([NK.getTerrain(meta), NK.loadBuildings(W)]);
    } catch (e) { console.warn(e); fail("The 3D data didn't load just now. Reload the page to try again."); return; }
    const labelsEl = $("#p3-labels"), ctl = $("#p3-ctl"), msg = $("#p3-msg");
    const towns = W.base.labels.filter((l) => l.k === "town" && (meta.towns || []).some((t) => t.n === l.n && t.core));
    if (labelsEl) labelsEl.innerHTML = towns.map((l) => `<span data-town="${esc(l.n)}">${esc(l.n.toUpperCase())}</span>`).join("");
    const spans = labelsEl ? $$("span", labelsEl) : [];
    let labelsOn = true, m3 = null;
    function placeLabels(m) {
      if (!labelsOn || !labelsEl) return;
      towns.forEach((l, i) => {
        const p = m.project(l.x, l.y, 90), el = spans[i];
        const vis = p.visible && p.x > -80 && p.y > -20 && p.x < host.clientWidth + 80 && p.y < host.clientHeight + 20;
        el.style.visibility = vis ? "visible" : "hidden";
        if (vis) el.style.transform = `translate(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px) translate(-50%, -50%)`;
      });
    }
    async function build() {
      if (m3) { m3.stopped = true; try { m3.renderer.dispose(); } catch (e) { /* ignore */ } host.innerHTML = ""; }
      try { m3 = new NK.Map3D(host, W, { onFrame: placeLabels }); } catch (e) {
        console.warn(e);
        fail("This browser can't draw the 3D view (WebGL is turned off or unavailable). The flat map works everywhere.");
        return false;
      }
      await m3.build(T, bld);
      return true;
    }
    if (!(await build())) return;
    if (loading) loading.hidden = true;
    if (ctl) ctl.hidden = false;
    S.onTheme(async () => {
      const v = m3 ? { x: m3.target.x, y: m3.target.z, dist: m3.dist, pitch: m3.pitch, yaw: m3.yaw } : null;
      if (await build() && v) { m3.target.set(v.x, m3.target.y, v.y); m3.dist = v.dist; m3.pitch = v.pitch; m3.yaw = v.yaw; m3.auto = false; }
    });
    ex.addEventListener("click", (e) => {
      const b = e.target.closest("[data-go]");
      if (b && m3 && VIEWS[b.dataset.go]) m3.goTo(VIEWS[b.dataset.go]);
    });
    const tl = $("#p3-town");
    tl?.addEventListener("click", () => {
      labelsOn = !labelsOn;
      tl.setAttribute("aria-pressed", String(labelsOn));
      if (labelsEl) labelsEl.hidden = !labelsOn;
    });
    /* poster mode: the controls step aside for a title block and the credit line */
    const pb = $("#p3-poster"), exitB = $("#p3-exit"), title = $("#p3-title"), head = $("#p3-head");
    function poster(on) {
      ex.toggleAttribute("data-poster", on);
      pb?.setAttribute("aria-pressed", String(on));
      if (title) title.hidden = !on;
      if (exitB) exitB.hidden = !on;
      if (ctl) ctl.hidden = on;
      if (head) head.hidden = on;
      (on ? exitB : pb)?.focus();
    }
    pb?.addEventListener("click", () => poster(true));
    exitB?.addEventListener("click", () => poster(false));
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && ex.hasAttribute("data-poster")) poster(false); });
    /* save as image: the WebGL frame at 2x, with the town labels, the title in poster mode and the credit line drawn on */
    $("#p3-save")?.addEventListener("click", async (e) => {
      const btn = e.currentTarget;
      btn.disabled = true;
      try {
        const url = m3.snapshot(2);
        const img = await new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = url; });
        const c = document.createElement("canvas");
        c.width = img.width; c.height = img.height;
        const ctx = c.getContext("2d"), k = img.width / host.clientWidth;
        ctx.drawImage(img, 0, 0);
        const ink = NK.css("--map-label") || "#1c232a", halo = NK.css("--map-halo") || "rgba(255,255,255,.9)";
        const text = (t, x, y, font, align = "center") => {
          ctx.font = font; ctx.textAlign = align; ctx.textBaseline = "middle"; ctx.lineJoin = "round";
          ctx.lineWidth = 4 * k; ctx.strokeStyle = halo; ctx.strokeText(t, x, y); ctx.fillStyle = ink; ctx.fillText(t, x, y);
        };
        if (labelsOn) towns.forEach((l) => { const p = m3.project(l.x, l.y, 90); if (p.visible) text(l.n.toUpperCase(), p.x * k, p.y * k, `800 ${15 * k}px ${NK.css("--f-display")}`); });
        if (ex.hasAttribute("data-poster")) {
          text("NK15068", c.width / 2, c.height - 96 * k, `800 ${40 * k}px ${NK.css("--f-display")}`);
          text("New Kensington · Arnold · Lower Burrell", c.width / 2, c.height - 58 * k, `600 ${17 * k}px ${NK.css("--f-body")}`);
        }
        text("Map data © OpenStreetMap contributors · Overture Maps · US Census · AWS Terrain Tiles", c.width - 12 * k, c.height - 14 * k, `400 ${11 * k}px ${NK.css("--f-body")}`, "right");
        const blob = await new Promise((ok) => c.toBlob(ok, "image/png"));
        const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(blob), download: "15068-3d.png" });
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 4000);
        if (msg) msg.textContent = `Saved a ${fmt(c.width)} × ${fmt(c.height)} image.`;
      } catch (err) {
        console.warn(err);
        if (msg) msg.textContent = "The image couldn't be made in this browser.";
      }
      btn.disabled = false;
    });
  }

  /* ======================================================================== /directory/ */
  S.pages.directory = () => directoryPage().catch((e) => { console.warn(e); });

  async function directoryPage() {
    const NK = window.NK, tools = $("#dir-tools"), table = $("#dir-table"), count = $("#dir-count"), more = $("#dir-more");
    if (!NK || !table || !tools) return;
    let places, streets, meta;
    try { [places, streets, meta] = await Promise.all([NK.getJSON("places.json"), NK.getJSON("streets.json"), NK.getJSON("meta.json")]); }
    catch (e) { console.warn(e); return; } // the first 100 rows are already on the page
    const rows = dedupe(places).sort(aToZ);
    const seen = new Set();
    const sts = streets.filter((s) => !seen.has(s.n) && seen.add(s.n)).sort(aToZ);
    const inp = $("#dir-q"), selT = $("#dir-town"), selG = $("#dir-g"), tabs = $("#dir-tabs");
    const Q = S.qs();
    const st = { tab: Q.get("tab") === "streets" ? "streets" : "places", q: (Q.get("q") || "").slice(0, 80), town: Q.get("town") || "", g: Q.get("g") || "", limit: 100 };
    if (st.town && selT && ![...selT.options].some((o) => o.value === st.town)) selT.insertAdjacentHTML("beforeend", `<option value="${esc(st.town)}">${esc(st.town)}</option>`);
    if (st.g && !meta.groups[st.g]) st.g = "";
    tools.hidden = false;
    if (inp) inp.value = st.q;
    if (selT) selT.value = st.town;
    if (selG) selG.value = st.g;
    const hay = (p) => (p._h || (p._h = [p.n, p.c, townLabel(p), p.a, meta.groups[p.g]].join(" ").toLowerCase()));
    const telCell = (ph) => { const t = S.tels(ph)[0]; return t ? `<a class="dtel" href="${t[1]}">${esc(t[0])}</a>` : esc(ph || ""); };
    const placeRow = (p) => `<tr><td class="dn"><a href="${esc(mapURL("place", placeParam(p)))}"><span class="dot" style="background:${NK.GROUP_COLORS[p.g] || "#7a8a99"}"></span>${esc(p.n)}</a><span class="sub">${esc(meta.groups[p.g] || "")}</span></td><td class="dc">${esc(p.c || "")}</td><td class="dt">${esc(townLabel(p))}</td><td class="da">${esc(p.a || "")}</td><td class="dp">${telCell(p.ph)}</td></tr>`;
    const streetRow = (s) => `<tr><td class="dn"><a href="${esc(mapURL("street", s.n))}">${esc(s.n)}</a>${S.routes(s.ref)}</td><td class="dt">${esc((s.t || []).map(townName).join(", "))}</td><td class="num dl">${fmt(s.m)} m</td><td class="num dd${s.a ? "" : " none"}">${s.a ? `${fmt(s.a)}<span class="ph-u"> ${plural(s.a, "address", "addresses")}</span>` : "–"}</td></tr>`;
    function draw() {
      const t = st.q.trim().toLowerCase();
      let list, head, noun;
      if (st.tab === "places") {
        list = rows.filter((p) => (!t || hay(p).includes(t)) && (!st.town || townLabel(p) === st.town) && (!st.g || p.g === st.g));
        head = "<tr><th>Name</th><th>Type</th><th>Town</th><th>Address</th><th>Phone</th></tr>";
        noun = "place";
      } else {
        list = sts.filter((s) => (!t || (s.n + " " + (s.t || []).join(" ") + " " + (s.ref || []).join(" ")).toLowerCase().includes(t)) && (!st.town || (s.t || []).includes(st.town) || (s.t || []).map(townName).includes(st.town)));
        head = `<tr><th>Street</th><th>Town</th><th class="num">Length</th><th class="num">Addresses</th></tr>`;
        noun = "street";
      }
      table.classList.toggle("streets", st.tab === "streets");
      const shown = list.slice(0, st.limit);
      table.innerHTML = `<thead>${head}</thead><tbody>${shown.map(st.tab === "places" ? placeRow : streetRow).join("")
        || `<tr><td colspan="5" class="empty">Nothing matches${st.q ? ` “${esc(st.q)}”` : ""}${st.town ? ` in ${esc(st.town)}` : ""}.</td></tr>`}</tbody>`;
      if (count) count.textContent = list.length > shown.length
        ? `Showing ${fmt(shown.length)} of ${fmt(list.length)} ${noun}s, A to Z.`
        : `${fmt(list.length)} ${plural(list.length, noun)}${list.length > 1 ? ", A to Z" : ""}.`;
      if (more) { more.hidden = list.length <= st.limit; more.textContent = `Show ${fmt(Math.min(100, list.length - st.limit))} more`; }
      if (selG) selG.hidden = st.tab !== "places";
      $$(".tab", tabs).forEach((b) => b.setAttribute("aria-selected", String(b.dataset.t === st.tab)));
      S.setQS({ q: st.q.trim(), town: st.town, tab: st.tab === "streets" ? "streets" : null, g: st.tab === "places" ? st.g : null });
      S.fadeWide();
    }
    tabs?.addEventListener("click", (e) => { const b = e.target.closest(".tab"); if (b) { st.tab = b.dataset.t; st.limit = 100; draw(); } });
    let timer = 0;
    inp?.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(() => { st.q = inp.value.slice(0, 80); st.limit = 100; draw(); }, 120); });
    selT?.addEventListener("change", () => { st.town = selT.value; st.limit = 100; draw(); });
    selG?.addEventListener("change", () => { st.g = selG.value; st.limit = 100; draw(); });
    more?.addEventListener("click", () => { st.limit += 100; draw(); });
    draw();
  }

  /* ======================================================================== /search/ */
  S.pages.search = () => searchPage().catch((e) => { console.warn(e); });

  const TITLES = { call: "Call", pages: "Pages", corner: "Corner", streets: "Streets", places: "Places", events: "What's on", news: "News", pets: "Lost & found listings" };
  async function searchPage() {
    const X = window.NKSearch, form = $("#sq"), input = $("#sq-q"), out = $("#sresults");
    if (!X || !form || !input || !out) return;
    const gapText = $("#s-gap") ? $("#s-gap").textContent : "";
    input.value = S.qs().get("q") || "";
    let data = null, posts = [], openPlaces = false;
    const P = window.NKPets;
    if (P) P.loadBoard({ ui: { onChange: (ps) => { posts = P.board.state === "listed" || P.board.state === "stale" ? ps : []; if (data && input.value.trim()) render(); } } });
    const today = S.isoDay(new Date());
    const hint = () => `<p class="s-hint">Try ${["police", "lost dog", "city hall", "pizza", "5th Ave"].map((w) => `<a href="?q=${encodeURIComponent(w)}">${esc(w)}</a>`).join(", ")}, or a corner like <a href="?q=${encodeURIComponent("5th & 9th")}">5th &amp; 9th</a>.</p>`;
    const group = (k, inner, extra = "") => `<section class="sgroup" data-group="${k}" aria-labelledby="sg-${k}"><h2 class="lh" id="sg-${k}">${TITLES[k]}</h2>${inner}${extra}</section>`;
    const li = (main, sub, tail = "") => `<li class="srow"><div class="sr-t">${main}${sub ? `<small>${sub}</small>` : ""}</div>${tail}</li>`;
    function render() {
      const q = input.value.trim();
      if (!q) { out.innerHTML = hint(); return; }
      const m = X.match(q, data, { town: S.town(), pets: posts });
      const G = m.groups, html = [];
      if (G.call.length || m.gap) {
        const rows = G.call.slice(0, 6).map((r) => {
          const [first, ...alt] = r.ph;
          const tail = first ? `<div class="sr-c">${S.telLink(first, "Call {n}")}${alt.map((p) => `<span class="tel-alt">or ${S.telLink(p, "{n}", "alt")}</span>`).join("")}</div>`
            : `<div class="sr-c"><a class="go" href="${esc(S.url(r.u))}">Details ›</a></div>`;
          return li(`<a href="${esc(S.url(r.u))}">${esc(r.n)}</a>`, esc(r.t), tail);
        }).join("");
        html.push(group("call", `<ul class="slist">${rows}</ul>`, (m.gap && gapText ? `<p class="s-gapline">${esc(gapText)}</p>` : "")
          + `<p><a class="go" href="${esc(S.url("numbers/"))}">All phone numbers ›</a></p>`));
      }
      if (G.pages.length) html.push(group("pages", `<ul class="slist">${G.pages.slice(0, 6).map((r) => li(`<a href="${esc(S.url(r.u))}">${esc(r.t)}</a>`, "")).join("")}</ul>`));
      if (G.corner.length) html.push(group("corner", `<p><a class="go" href="${esc(mapURL("near", G.corner[0].text))}">Find “${esc(G.corner[0].text)}” on the map ›</a></p>`));
      if (G.streets.length) html.push(group("streets", `<ul class="slist">${G.streets.slice(0, 8).map((s) => li(
        `<a href="${esc(mapURL("street", s.n))}">${esc(s.n)}</a>${S.routes(s.ref)}`,
        esc([(s.t || []).map(townName).join(", "), `${fmt(s.m)} m`].filter(Boolean).join(" · ")),
        s._inc ? `<div class="sr-c"><a class="go" href="${esc(S.url(s._inc.u))}">${s._inc.n} news-reported ${plural(s._inc.n, "incident")} on this street ›</a></div>` : "")).join("")}</ul>`));
      if (G.places.length) {
        const n = G.places.length, show = openPlaces ? G.places : G.places.slice(0, 10);
        html.push(group("places", `<ul class="slist">${show.map((p) => li(`<a href="${esc(mapURL("place", placeParam(p)))}">${esc(p.n)}</a>`,
          esc([S.cap(p.c || ""), p._town, S.shortAddr(p.a)].filter(Boolean).join(" · ")),
          p.ph && S.tels(p.ph).length ? `<div class="sr-c">${S.telLink(p.ph, "Call {n}")}</div>` : "")).join("")}</ul>`,
          n > show.length ? `<button type="button" class="btn-line inline" id="s-all">Show all ${fmt(n)}</button>` : ""));
      }
      const events = G.events.filter((e) => !e.next || e.next >= today);
      if (events.length) html.push(group("events", `<ul class="slist">${events.slice(0, 6).map((e) => li(`<a href="${esc(S.url(e.u))}">${esc(e.n)}</a>`, esc(e.label))).join("")}</ul>`));
      if (G.news.length) html.push(group("news", `<ul class="slist">${G.news.slice(0, 6).map((r) => li(`<a href="${esc(S.url(r.u))}">${esc(r.h)}</a>`, esc(`${S.apDate(r.d, r.about)} · ${r.o}`))).join("")}</ul>`));
      if (G.pets.length && P) html.push(group("pets", `<ul class="petrows">${G.pets.slice(0, 6).map(P.rowHTML).join("")}</ul>`));
      out.innerHTML = html.join("") || `<p class="s-empty">Nothing found for “${esc(q)}”. Try a business, a street (“5th Ave”), a corner (“5th & 9th”) or a topic like “police”, “lost dog” or “city hall”.</p>`;
      S.relabel(out);
    }
    out.addEventListener("click", (e) => { if (e.target.closest("#s-all")) { openPlaces = true; render(); } });
    form.addEventListener("submit", (e) => { e.preventDefault(); openPlaces = false; S.setQS({ q: input.value.trim() }); render(); });
    let timer = 0;
    input.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(() => { openPlaces = false; S.setQS({ q: input.value.trim() }); if (data) render(); }, 200); });
    out.innerHTML = input.value.trim() ? `<p class="s-hint">Searching…</p>` : hint();
    try { data = await X.load(); } catch (e) {
      console.warn(e);
      out.innerHTML = `<p class="s-empty">Search didn't load just now. Try <a href="${esc(S.url("numbers/"))}">Phone numbers</a>, <a href="${esc(S.url("lost-pets/"))}">Lost pets</a> or <a href="${esc(S.url("directory/"))}">Places and streets A to Z</a>.</p>`;
      return;
    }
    render();
  }
})();

/* ==== js/99-boot.js ==== */
/* NK15068 — run this page's module (the page id is <html data-page>) */
(function () {
  "use strict";
  const page = document.documentElement.dataset.page;
  const run = window.NKS && window.NKS.pages[page];
  if (!run) return;
  try {
    const r = run();
    if (r && typeof r.catch === "function") r.catch((e) => console.error(e));
  } catch (e) {
    console.error(e);
  }
})();
